{
  "name": "Bookgram",
  "description": "A modern exchange for students to buy, rent, and share knowledge sustainably. Features an AI book curator."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum View {
  STORE = 'STORE',
  COMMUNITY = 'COMMUNITY',
  AI_HELPER = 'AI_HELPER',
  PROFILE = 'PROFILE',
}

export interface Book {
  id: string;
  title: string;
  author: string;
  description: string;
  category: string;
  priceBuy: number;
  priceRent: number;
  imageUrl: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  rentedBooks: string[]; // Book IDs
  boughtBooks: string[]; // Book IDs
}

export enum AuthMode {
  LOGIN = 'LOGIN',
  SIGNUP = 'SIGNUP',
}

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import BookStore from './components/BookStore';
import AIHelper from './components/AIHelper';
import AuthModal from './components/Auth';
import AddBookModal from './components/AddBook';
import { View, User, Book } from './types';
import { BookOpen, User as UserIcon, MessageSquare } from 'lucide-react';

// Mock Initial Data
const INITIAL_BOOKS: Book[] = [
  {
    id: '1',
    title: 'Concepts of Physics',
    author: 'H.C. Verma',
    category: 'Engineering',
    description: 'A classic textbook for physics enthusiasts and engineering aspirants.',
    priceBuy: 450,
    priceRent: 150,
    imageUrl: 'https://picsum.photos/200/300?random=1',
  },
  {
    id: '2',
    title: 'Gray\'s Anatomy',
    author: 'Henry Gray',
    category: 'Medical',
    description: 'The definitive anatomy textbook for medical students.',
    priceBuy: 1200,
    priceRent: 300,
    imageUrl: 'https://picsum.photos/200/300?random=2',
  },
  {
    id: '3',
    title: 'Sapiens: A Brief History',
    author: 'Yuval Noah Harari',
    category: 'Non-Fiction',
    description: 'A bold and provocative look at our species.',
    priceBuy: 500,
    priceRent: 100,
    imageUrl: 'https://picsum.photos/200/300?random=3',
  },
  {
    id: '4',
    title: 'The Great Gatsby',
    author: 'F. Scott Fitzgerald',
    category: 'Fiction',
    description: 'A novel about the American dream and the roaring twenties.',
    priceBuy: 300,
    priceRent: 50,
    imageUrl: 'https://picsum.photos/200/300?random=4',
  },
  {
    id: '5',
    title: 'Introduction to Algorithms',
    author: 'Cormen et al.',
    category: 'Engineering',
    description: 'Essential guide to algorithms for computer science students.',
    priceBuy: 900,
    priceRent: 250,
    imageUrl: 'https://picsum.photos/200/300?random=5',
  },
];

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.STORE);
  const [user, setUser] = useState<User | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showAddBookModal, setShowAddBookModal] = useState(false);
  const [books, setBooks] = useState<Book[]>(INITIAL_BOOKS);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // Toggle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogin = (userData: User) => {
    setUser(userData);
    setShowAuthModal(false);
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView(View.STORE);
  };

  const handleAddBook = (newBook: Book) => {
    setBooks([newBook, ...books]);
    setShowAddBookModal(false);
    setCurrentView(View.STORE);
  };

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      <Navbar
        currentView={currentView}
        setCurrentView={setCurrentView}
        user={user}
        onLoginClick={() => setShowAuthModal(true)}
        onLogoutClick={handleLogout}
        onPostBookClick={() => {
          if (!user) {
            setShowAuthModal(true);
          } else {
            setShowAddBookModal(true);
          }
        }}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
      />

      <main className="flex-grow container mx-auto px-4 py-8">
        {currentView === View.STORE && (
          <>
            <Hero />
            <BookStore
              books={books}
              user={user}
              onBuy={(book) => alert(`You purchased ${book.title} for ₹${book.priceBuy}!`)}
              onRent={(book) => alert(`You rented ${book.title} for ₹${book.priceRent}!`)}
            />
          </>
        )}

        {currentView === View.AI_HELPER && (
          <AIHelper />
        )}

        {currentView === View.COMMUNITY && (
          <div className="flex flex-col items-center justify-center h-96 text-center text-gray-500 dark:text-gray-400">
            <MessageSquare size={64} className="mb-4 text-lightGreen" />
            <h2 className="text-3xl font-serif mb-2 text-primaryGreen dark:text-cream">Community Hub</h2>
            <p>Connect with other readers, join book clubs, and discuss your favorite reads. (Coming Soon)</p>
          </div>
        )}

        {currentView === View.PROFILE && user && (
          <div className="max-w-4xl mx-auto bg-white dark:bg-bgDark p-8 rounded-3xl shadow-lg border border-gray-200 dark:border-primaryGreen/30">
            <div className="flex items-center gap-6 mb-8">
              <div className="w-24 h-24 bg-lightGreen rounded-full flex items-center justify-center text-bgDarker text-4xl font-bold">
                {user.name.charAt(0).toUpperCase()}
              </div>
              <div>
                <h2 className="text-3xl font-serif font-bold text-gray-800 dark:text-cream">{user.name}</h2>
                <p className="text-gray-500 dark:text-gray-400">{user.email}</p>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-creamLight dark:bg-bgDarker p-6 rounded-2xl">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
                   <BookOpen size={20} /> Rented Books
                </h3>
                {user.rentedBooks.length === 0 ? <p className="text-sm opacity-70">No active rentals.</p> : <p>{user.rentedBooks.length} Active</p>}
              </div>
               <div className="bg-creamLight dark:bg-bgDarker p-6 rounded-2xl">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2">
                   <BookOpen size={20} /> Purchased Books
                </h3>
                {user.boughtBooks.length === 0 ? <p className="text-sm opacity-70">No purchases yet.</p> : <p>{user.boughtBooks.length} Owned</p>}
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} onLogin={handleLogin} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

export default App;

import React from 'react';
