interface BookDetailsProps {
  book: Book;
  onClose: () => void;
  onAddToCart: (item: CartItem) => void;
}

const BookDetails: React.FC<BookDetailsProps> = ({ book, onClose, onAddToCart }) => {
  const [rentWeeks, setRentWeeks] = useState(1);
  const [mode, setMode] = useState<'BUY' | 'RENT'>('RENT');

  const handleAddToCart = () => {
    const price = mode === 'BUY' ? book.priceBuy : book.priceRent * rentWeeks;

    const cartItem: CartItem = {
      id: Date.now().toString(),
      bookId: book.id,
      title: book.title,
      author: book.author,
      imageUrl: book.imageUrl,
      type: mode,
      rentWeeks: mode === 'RENT' ? rentWeeks : undefined,
      price: price
    };

    onAddToCart(cartItem);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm animate-in fade-in duration-200">
