             onClick={onClose}
             className="absolute top-4 left-4 md:hidden w-10 h-10 rounded-full bg-black/50 text-white flex items-center justify-center backdrop-blur-md"
           >
             <X size={24} />
           </button>
        </div>

        {/* Details Section */}
        <div className="w-full md:w-3/5 p-8 flex flex-col overflow-y-auto">
          <div className="flex justify-between items-start mb-6">
            <div>
              <span className="text-primaryGreen font-bold text-sm tracking-widest uppercase">{book.category}</span>
              <h2 className="text-3xl md:text-4xl font-serif font-bold text-gray-900 dark:text-cream mt-2 leading-tight">
                {book.title}
              </h2>
              <p className="text-lg text-gray-500 dark:text-gray-400 mt-1">{book.author}</p>
            </div>
            <button 
             onClick={onClose}
             className="hidden md:flex w-10 h-10 rounded-full bg-gray-100 dark:bg-white/10 hover:bg-gray-200 dark:hover:bg-white/20 text-gray-500 dark:text-cream items-center justify-center transition-colors"
           >
             <X size={24} />
           </button>
          </div>

          <p className="text-gray-600 dark:text-gray-300 leading-relaxed mb-8">
            {book.description}
          </p>

          <div className="mt-auto space-y-6">
            {/* Toggle Mode */}
