               <div 
                 className={`absolute top-1 bottom-1 w-1/2 bg-white dark:bg-white/10 rounded-xl shadow-sm transition-all duration-300 ${mode === 'BUY' ? 'left-1' : 'left-[49%]'}`}
               />
               <button 
                 onClick={() => setMode('BUY')}
