               >
                 Buy (₹{book.priceBuy})
               </button>
               <button 
                 onClick={() => setMode('RENT')}
                 className={`flex-1 relative z-10 py-3 text-center font-bold text-sm transition-colors ${mode === 'RENT' ? 'text-gray-900 dark:text-cream' : 'text-gray-500'}`}
               >
                 Rent (₹{book.priceRent}/wk)
               </button>
            </div>

            {/* Rent Logic */}
            {mode === 'RENT' && (
              <div className="bg-creamLight dark:bg-white/5 p-6 rounded-2xl border border-primaryGreen/20">
                 <div className="flex items-center justify-between mb-4">
                    <label className="font-medium text-gray-700 dark:text-gray-300 flex items-center gap-2">
                      <Clock size={18} /> Rent Duration
                    </label>
                    <div className="flex items-center gap-3">
                       <button 
                         onClick={() => setRentWeeks(Math.max(1, rentWeeks - 1))}
                         className="w-8 h-8 rounded-lg bg-white dark:bg-white/10 flex items-center justify-center font-bold shadow-sm"
                       >-</button>
                       <span className="font-bold w-12 text-center">{rentWeeks} wk</span>
                       <button 
                         onClick={() => setRentWeeks(rentWeeks + 1)}
                         className="w-8 h-8 rounded-lg bg-white dark:bg-white/10 flex items-center justify-center font-bold shadow-sm"
                       >+</button>
                    </div>
                 </div>
                 <div className="flex items-center justify-between pt-4 border-t border-gray-200 dark:border-white/10">
                    <span className="text-sm text-gray-500">Total Rent Price</span>
                    <span className="text-2xl font-bold text-primaryGreen">₹{book.priceRent * rentWeeks}</span>
                 </div>
              </div>
            )}

            {/* Total Price for Buy */}
            {mode === 'BUY' && (
              <div className="bg-creamLight dark:bg-white/5 p-6 rounded-2xl border border-primaryGreen/20 flex items-center justify-between">
                  <span className="text-gray-700 dark:text-gray-300 font-medium">Purchase Price</span>
                  <span className="text-2xl font-bold text-gray-900 dark:text-cream">₹{book.priceBuy}</span>
              </div>
            )}

            <button
              onClick={handleAddToCart}
              className="w-full bg-primaryGreen hover:bg-opacity-90 text-white font-bold py-4 rounded-xl shadow-lg shadow-primaryGreen/20 flex items-center justify-center gap-2 transition-transform active:scale-95"
            >
              <ShoppingBag size={20} />
              Add to Cart - ₹{mode === 'BUY' ? book.priceBuy : book.priceRent * rentWeeks}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default BookDetails;

import React from 'react';
