              </div>

              <div className="text-right">
                <span className="block font-bold text-xl text-primaryGreen">₹{item.price}</span>
              </div>
            </div>
          ))}
        </div>

        {/* Summary */}
        <div className="w-full lg:w-96 flex-shrink-0">
          <div className="bg-white dark:bg-bgDark p-6 rounded-2xl shadow-lg border border-gray-100 dark:border-white/5 sticky top-24">
            <h3 className="text-xl font-bold text-gray-900 dark:text-cream mb-6">Order Summary</h3>

            <div className="space-y-3 mb-6">
              <div className="flex justify-between text-gray-600 dark:text-gray-400">
                <span>Subtotal ({items.length} items)</span>
                <span>₹{total}</span>
              </div>
              <div className="flex justify-between text-gray-600 dark:text-gray-400">
                <span>Taxes & Fees</span>
                <span>₹{Math.round(total * 0.05)}</span>
              </div>
              <div className="border-t border-gray-200 dark:border-white/10 my-4"></div>
              <div className="flex justify-between text-xl font-bold text-gray-900 dark:text-cream">
                <span>Total</span>
                <span>₹{total + Math.round(total * 0.05)}</span>
              </div>
