const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.STORE);
  const [user, setUser] = useState<User | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showAddBookModal, setShowAddBookModal] = useState(false);
  const [books, setBooks] = useState<Book[]>(INITIAL_BOOKS);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // New States for Shopping Flow
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);

  // Toggle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogin = (userData: User) => {
    setUser(userData);
    setShowAuthModal(false);
  };

  const handleLogout = () => {
    setUser(null);
    setCurrentView(View.STORE);
  };

  const handleAddBook = (newBook: Book) => {
    setBooks([newBook, ...books]);
    setShowAddBookModal(false);
    setCurrentView(View.STORE);
  };

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Cart Functions
  const handleAddToCart = (item: CartItem) => {
    setCart([...cart, item]);
    alert(`${item.title} added to cart!`);
  };

  const handleRemoveFromCart = (itemId: string) => {
    setCart(cart.filter(item => item.id !== itemId));
  };

  const handlePlaceOrder = (address: any, paymentMethod: string) => {
    if (!user) {
      alert("Please login to complete purchase.");
      setShowAuthModal(true);
      return;
    }

    // Update User Profile with purchased/rented books
    const newBought = [...user.boughtBooks];
    const newRented = [...user.rentedBooks];

    cart.forEach(item => {
      if (item.type === 'BUY') newBought.push(item.bookId);
      else newRented.push(item.bookId);
    });

    setUser({ ...user, boughtBooks: newBought, rentedBooks: newRented });
    setCart([]);
    setCurrentView(View.ORDER_SUCCESS);
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      <Navbar
        currentView={currentView}
        setCurrentView={setCurrentView}
        user={user}
        onLoginClick={() => setShowAuthModal(true)}
        onLogoutClick={handleLogout}
        onPostBookClick={() => {
          if (!user) {
            setShowAuthModal(true);
          } else {
            setShowAddBookModal(true);
          }
        }}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
        cartItemCount={cart.length}
      />

      <main className="flex-grow container mx-auto px-4 py-8">
        {currentView === View.STORE && (
          <>
            <Hero />
            <BookStore
              books={books}
              user={user}
              onBookClick={(book) => {
                setSelectedBook(book);
                setCurrentView(View.BOOK_DETAILS);
              }}
            />
          </>
        )}

        {currentView === View.BOOK_DETAILS && selectedBook && (
          <BookDetails 
            book={selectedBook} 
            onBack={() => {
              setSelectedBook(null);
              setCurrentView(View.STORE);
            }} 
            onAddToCart={handleAddToCart}
          />
        )}

        {currentView === View.CART && (
          <Cart 
            items={cart} 
            onRemove={handleRemoveFromCart}
            onCheckout={() => {
              if (cart.length > 0) setCurrentView(View.CHECKOUT);
            }}
            onContinueShopping={() => setCurrentView(View.STORE)}
          />
        )}

        {currentView === View.CHECKOUT && (
          <Checkout 
            total={cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05)}
            onBack={() => setCurrentView(View.CART)}
            onPlaceOrder={handlePlaceOrder}
          />
        )}

        {currentView === View.ORDER_SUCCESS && (
          <OrderSuccess onContinue={() => setCurrentView(View.STORE)} />
        )}

        {currentView === View.AI_HELPER && (
          <AIHelper />
        )}

        {currentView === View.COMMUNITY && (
          <Community user={user} />
        )}

        {currentView === View.PROFILE && user && (
          <div className="max-w-4xl mx-auto bg-white dark:bg-bgDark p-8 rounded-3xl shadow-lg border border-gray-200 dark:border-primaryGreen/30 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="flex items-center gap-6 mb-8">
              <div className="w-24 h-24 bg-lightGreen rounded-full flex items-center justify-center text-bgDarker text-4xl font-bold">
                {user.name.charAt(0).toUpperCase()}
              </div>
              <div>
                <h2 className="text-3xl font-serif font-bold text-gray-800 dark:text-cream">{user.name}</h2>
                <p className="text-gray-500 dark:text-gray-400">{user.email}</p>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-creamLight dark:bg-bgDarker p-6 rounded-2xl">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2 text-primaryGreen">
                   <BookOpen size={20} /> Rented Books
                </h3>
                {user.rentedBooks.length === 0 ? (
                  <p className="text-sm opacity-70">No active rentals.</p>
                ) : (
                  <ul className="space-y-2">
                    {user.rentedBooks.map((bid, i) => {
                      const b = books.find(book => book.id === bid);
                      return b ? <li key={i} className="text-sm border-b border-gray-200 dark:border-white/5 pb-2 last:border-0">{b.title}</li> : null;
                    })}
                  </ul>
                )}
              </div>
               <div className="bg-creamLight dark:bg-bgDarker p-6 rounded-2xl">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2 text-primaryGreen">
                   <BookOpen size={20} /> Purchased Books
                </h3>
                {user.boughtBooks.length === 0 ? (
                  <p className="text-sm opacity-70">No purchases yet.</p>
                ) : (
                  <ul className="space-y-2">
                    {user.boughtBooks.map((bid, i) => {
                      const b = books.find(book => book.id === bid);
                      return b ? <li key={i} className="text-sm border-b border-gray-200 dark:border-white/5 pb-2 last:border-0">{b.title}</li> : null;
                    })}
                  </ul>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} onLogin={handleLogin} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

export default App;

