              className="group cursor-pointer bg-white dark:bg-bgDarker rounded-3xl overflow-hidden border border-gray-200 dark:border-white/5 hover:border-primaryGreen/50 transition-all duration-300 hover:shadow-2xl hover:shadow-primaryGreen/10 flex flex-col h-full"
