                  <h3 className="font-serif text-xl font-bold text-gray-900 dark:text-cream leading-tight mb-1 line-clamp-1 group-hover:text-primaryGreen transition-colors">
                    {book.title}
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400 font-medium">{book.author}</p>
                </div>

                <div className="flex items-center gap-1 mb-4">
                   {[1,2,3,4,5].map(i => <Star key={i} size={12} className="fill-yellow-400 text-yellow-400" />)}
                   <span className="text-xs text-gray-400 ml-1">(4.5)</span>
