                ) : (
                  <ul className="space-y-2">
                    {user.boughtBooks.map((bid, i) => {
                      const b = books.find(book => book.id === bid);
                      return b ? <li key={i} className="text-sm border-b border-gray-200 dark:border-white/5 pb-2 last:border-0">{b.title}</li> : null;
                    })}
                  </ul>
                )}
              </div>

              {/* Favorite Books */}
              <div className="bg-creamLight dark:bg-bgDarker p-6 rounded-2xl">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2 text-primaryGreen">
                   <Heart size={20} className="fill-primaryGreen" /> Favorite Books
                </h3>
                {user.favoriteBooks.length === 0 ? (
                  <p className="text-sm opacity-70">Your wishlist is empty.</p>
                ) : (
                  <ul className="space-y-2">
                    {user.favoriteBooks.map((bid, i) => {
                      const b = books.find(book => book.id === bid);
                      return b ? <li key={i} className="text-sm border-b border-gray-200 dark:border-white/5 pb-2 last:border-0 cursor-pointer hover:text-primaryGreen" onClick={() => { setSelectedBook(b!); setCurrentView(View.BOOK_DETAILS); }}>{b.title}</li> : null;
                    })}
                  </ul>
                )}
              </div>

              {/* Listed Books */}
              <div className="bg-creamLight dark:bg-bgDarker p-6 rounded-2xl">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2 text-primaryGreen">
                   <Bookmark size={20} /> Listed for Sale/Rent
                </h3>
                {user.listedBooks.length === 0 ? (
                  <p className="text-sm opacity-70">You haven't listed any books.</p>
                ) : (
                  <ul className="space-y-2">
                    {user.listedBooks.map((bid, i) => {
                      const b = books.find(book => book.id === bid);
                      return b ? <li key={i} className="text-sm border-b border-gray-200 dark:border-white/5 pb-2 last:border-0">{b.title}</li> : null;
                    })}
                  </ul>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} onLogin={handleLogin} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

