              </div>

              <button
                type="submit"
                className="w-full bg-primaryGreen hover:bg-opacity-90 text-white font-bold py-3.5 rounded-xl shadow-lg shadow-primaryGreen/20 transition-all mt-2"
              >
                Post Question
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

