import React from 'react';
import { View, User } from '../types';
import { Moon, Sun, ShoppingCart, User as UserIcon } from 'lucide-react';

interface NavbarProps {
  currentView: View;
  setCurrentView: (view: View) => void;
  user: User | null;
  onLoginClick: () => void;
  onLogoutClick: () => void;
  onPostBookClick: () => void;
  isDarkMode: boolean;
  toggleTheme: () => void;
  cartItemCount: number;
}

const Navbar: React.FC<NavbarProps> = ({
  currentView,
  setCurrentView,
  user,
  onLoginClick,
  onLogoutClick,
  onPostBookClick,
  isDarkMode,
  toggleTheme,
  cartItemCount,
}) => {
  const navItems = [
    { label: 'Store', value: View.STORE },
    { label: 'Community', value: View.COMMUNITY },
    { label: 'AI Helper', value: View.AI_HELPER },
    { label: 'Contact', value: View.CONTACT },
  ];

  if (user) {
    navItems.push({ label: 'Profile', value: View.PROFILE });
  }

  return (
    <nav className="sticky top-0 z-50 w-full transition-colors duration-300 bg-cream/90 dark:bg-bgDarker/90 backdrop-blur-md border-b border-gray-200 dark:border-primaryGreen/20">
      <div className="container mx-auto px-4 py-4 flex items-center justify-between">
        {/* Logo */}
        <div 
          className="flex items-center gap-2 cursor-pointer group"
          onClick={() => setCurrentView(View.STORE)}
        >
          <div className="w-10 h-10 bg-primaryGreen rounded-lg flex items-center justify-center text-white font-bold text-xl group-hover:scale-105 transition-transform">
            B
          </div>
          <span className="text-2xl font-serif font-bold text-gray-800 dark:text-cream tracking-tight">
            Bookgram
          </span>
        </div>

        {/* Center Tabs */}
        <div className="hidden md:flex items-center bg-gray-200/50 dark:bg-bgDark/50 rounded-full p-1 border border-gray-200 dark:border-white/10">
          {navItems.map((item) => (
            <button
              key={item.value}
              onClick={() => setCurrentView(item.value)}
              className={`px-5 py-2 rounded-full text-sm font-medium transition-all duration-200 ${
                currentView === item.value
                  ? 'bg-primaryGreen text-white shadow-md'
                  : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-white/10'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>

        {/* Right Actions */}
        <div className="flex items-center gap-4">
          {/* Cart Icon */}
          <button
            onClick={() => setCurrentView(View.CART)}
            className="relative w-10 h-10 rounded-full flex items-center justify-center hover:bg-gray-100 dark:hover:bg-white/10 transition-colors"
          >
            <ShoppingCart size={22} className="text-gray-700 dark:text-cream" />
            {cartItemCount > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-cream dark:border-bgDarker">
                {cartItemCount}
              </span>
            )}
          </button>

          {/* Theme Toggle */}
          <button
            onClick={toggleTheme}
            className="w-10 h-10 rounded-full flex items-center justify-center bg-white dark:bg-white/10 border border-gray-200 dark:border-white/10 hover:border-blue-400 dark:hover:border-blue-400 group transition-all"
            aria-label="Toggle Theme"
          >
            {isDarkMode ? (
              <span className="text-xl">🌞</span> 
            ) : (
              <span className="text-xl">🌛</span>
            )}
          </button>

          {/* Post Book Button */}
          <button
            onClick={onPostBookClick}
            className="hidden sm:block px-6 py-2.5 bg-primaryGreen hover:bg-opacity-90 text-white rounded-xl font-medium shadow-lg shadow-primaryGreen/30 transition-all hover:scale-105 active:scale-95"
          >
            Post Book
          </button>

          {/* Mobile Profile/Login */}
           {!user ? (
            <button
              onClick={onLoginClick}
              className="md:hidden text-sm font-medium text-primaryGreen dark:text-lightGreen"
            >
              Login
            </button>
          ) : (
             <button onClick={onLogoutClick} className="md:hidden text-gray-500 hover:text-red-500">
                <UserIcon size={20} />
             </button>
          )}
        </div>
      </div>

      {/* Mobile Nav */}
      <div className="md:hidden flex justify-around py-3 bg-white dark:bg-bgDark border-t border-gray-200 dark:border-white/5">
         {navItems.map((item) => (
            <button
              key={item.value}
              onClick={() => setCurrentView(item.value)}
              className={`text-xs font-medium ${currentView === item.value ? 'text-primaryGreen' : 'text-gray-500'}`}
            >
              {item.label}
            </button>
          ))}
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import { Mail, Phone, User, Clock, MessageSquare, Send, CheckCircle } from 'lucide-react';

const Contact: React.FC = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    mobile: '',
    query: '',
    timeSlot: 'Morning (9 AM - 12 PM)'
  });
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate API call
    setTimeout(() => {
      setIsSubmitted(true);
    }, 800);
  };

  if (isSubmitted) {
    return (
      <div className="max-w-xl mx-auto py-20 px-6">
        <div className="bg-white dark:bg-bgDark p-10 rounded-3xl shadow-2xl border border-gray-100 dark:border-white/5 text-center animate-in fade-in zoom-in duration-500">
          <div className="w-24 h-24 bg-primaryGreen/10 rounded-full flex items-center justify-center mx-auto mb-6">
            <CheckCircle className="text-primaryGreen" size={48} />
          </div>
          <h2 className="text-4xl font-serif font-bold text-gray-900 dark:text-cream mb-4">Message Sent!</h2>
          <p className="text-gray-500 dark:text-gray-300 text-lg mb-8">
            Thank you for contacting us, <span className="font-bold text-primaryGreen">{formData.fullName}</span>. 
            <br className="hidden sm:block" />
            Our admin team will review your query and reach out to you at <span className="font-mono bg-gray-100 dark:bg-white/10 px-2 py-0.5 rounded text-sm">{formData.email}</span> during your preferred time slot of <span className="font-bold">{formData.timeSlot}</span>.
          </p>
          <button 
            onClick={() => {
              setIsSubmitted(false);
              setFormData({ fullName: '', email: '', mobile: '', query: '', timeSlot: 'Morning (9 AM - 12 PM)' });
            }}
            className="text-primaryGreen font-bold hover:underline"
          >
            Send another message
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto py-10 px-4">
      <div className="text-center mb-10 animate-in fade-in slide-in-from-top-4 duration-500">
        <h1 className="text-4xl md:text-5xl font-serif font-bold text-gray-900 dark:text-cream mb-4">Get in Touch</h1>
        <p className="text-gray-500 dark:text-gray-400 text-lg">
          Have a question about a book, an order, or just want to say hello? 
          <br className="hidden sm:block" />
          Fill out the form below and our admin team will assist you.
        </p>
      </div>

      <div className="bg-white dark:bg-bgDark p-8 md:p-10 rounded-3xl shadow-xl border border-gray-200 dark:border-white/5 animate-in fade-in slide-in-from-bottom-8 duration-500 delay-100">
        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Full Name */}
          <div>
            <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2 ml-1">Full Name</label>
            <div className="relative">
              <User className="absolute left-4 top-3.5 text-gray-400" size={20} />
              <input
                type="text"
                name="fullName"
                required
                value={formData.fullName}
                onChange={handleChange}
                placeholder="Jane Doe"
                className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-12 pr-4 py-3.5 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen focus:ring-1 focus:ring-primaryGreen transition-all"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Email */}
            <div>
              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2 ml-1">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-4 top-3.5 text-gray-400" size={20} />
                <input
                  type="email"
                  name="email"
                  required
                  value={formData.email}
                  onChange={handleChange}
                  placeholder="jane@example.com"
                  className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-12 pr-4 py-3.5 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen focus:ring-1 focus:ring-primaryGreen transition-all"
                />
              </div>
            </div>

            {/* Mobile */}
            <div>
              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2 ml-1">Mobile Number</label>
              <div className="relative">
                <Phone className="absolute left-4 top-3.5 text-gray-400" size={20} />
                <input
                  type="tel"
                  name="mobile"
                  required
                  value={formData.mobile}
                  onChange={handleChange}
                  placeholder="+91 98765 43210"
                  className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-12 pr-4 py-3.5 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen focus:ring-1 focus:ring-primaryGreen transition-all"
                />
              </div>
            </div>
          </div>

          {/* Time Slot */}
          <div>
            <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2 ml-1">Preferred Time Slot for Callback</label>
            <div className="relative">
              <Clock className="absolute left-4 top-3.5 text-gray-400" size={20} />
              <select
                name="timeSlot"
