  const [currentView, setCurrentView] = useState<View>(View.STORE);
  const [user, setUser] = useState<User | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showAddBookModal, setShowAddBookModal] = useState(false);
  const [books, setBooks] = useState<Book[]>(INITIAL_BOOKS);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // New States for Shopping Flow
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);

  // --- Supabase Integration ---

  // 1. Check for active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        fetchUserProfile(session.user);
      }
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        fetchUserProfile(session.user);
      } else {
        setUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // 2. Fetch Books from Supabase
  useEffect(() => {
    const fetchBooks = async () => {
      try {
        const { data, error } = await supabase.from('books').select('*');
        if (error) {
          console.log("Using local books (Supabase table 'books' not found or error):", error.message);
          return;
        }
        if (data && data.length > 0) {
          // Map database snake_case to frontend camelCase if necessary, 
          // or assume DB columns match. For now, we map assuming some diffs.
          const mappedBooks: Book[] = data.map((b: any) => ({
            id: b.id,
            title: b.title,
            author: b.author,
            description: b.description,
            category: b.category,
            priceBuy: b.price_buy || b.priceBuy,
            priceRent: b.price_rent || b.priceRent,
            imageUrl: b.image_url || b.imageUrl,
            images: b.images || [],
            reviews: b.reviews || [],
            averageRating: b.average_rating || b.averageRating || 0,
          }));
          setBooks(mappedBooks);
        }
      } catch (err) {
        console.error("Error connecting to DB:", err);
      }
    };
    fetchBooks();
  }, []);

  const fetchUserProfile = async (authUser: any) => {
    // Try to get profile from 'profiles' table
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .single();

      if (data && !error) {
        setUser({
          id: data.id,
          name: data.name || authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: data.avatar || authUser.user_metadata?.avatar_url,
          rentedBooks: data.rented_books || [],
          boughtBooks: data.bought_books || [],
          favoriteBooks: data.favorite_books || [],
          listedBooks: data.listed_books || [],
        });
      } else {
        // Fallback if profile table doesn't exist yet
        setUser({
          id: authUser.id,
          name: authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: authUser.user_metadata?.avatar_url,
          rentedBooks: [],
          boughtBooks: [],
          favoriteBooks: [],
          listedBooks: [],
        });
      }
    } catch (error) {
       // Fallback on error
       setUser({
        id: authUser.id,
        name: authUser.user_metadata?.full_name || 'User',
        email: authUser.email,
        avatar: authUser.user_metadata?.avatar_url,
        rentedBooks: [],
        boughtBooks: [],
        favoriteBooks: [],
        listedBooks: [],
      });
    }
  };

  // --- End Supabase Integration ---

  // Toggle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setCurrentView(View.STORE);
  };

  const handleUpdateUser = (updatedUser: User) => {
    setUser(updatedUser);
    // In a real app, we would update Supabase 'profiles' table here
  };

  const handleAddBook = async (newBook: Book) => {
    // Optimistic Update
    setBooks([newBook, ...books]);
    if (user) {
      setUser({ ...user, listedBooks: [newBook.id, ...user.listedBooks] });
    }

    // Attempt to save to Supabase
    try {
      const dbBook = {
        id: newBook.id,
        title: newBook.title,
        author: newBook.author,
        description: newBook.description,
        category: newBook.category,
        price_buy: newBook.priceBuy,
        price_rent: newBook.priceRent,
        image_url: newBook.imageUrl,
        images: newBook.images,
        average_rating: newBook.averageRating,
        reviews: newBook.reviews
      };

      const { error } = await supabase.from('books').insert([dbBook]);
      if (error) console.error("Error saving book to DB:", error.message);
    } catch (e) {
      console.error("Failed to save book to Supabase");
    }

    setShowAddBookModal(false);
    setCurrentView(View.STORE);
  };

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Cart Functions
  const handleAddToCart = (item: CartItem) => {
    setCart([...cart, item]);
    alert(`${item.title} added to cart!`);
  };

  const handleRemoveFromCart = (itemId: string) => {
    setCart(cart.filter(item => item.id !== itemId));
  };

  const handleUpdateQuantity = (itemId: string, newQuantity: number) => {
    if (newQuantity < 1) return;
    setCart(cart.map(item => {
      if (item.id === itemId) {
        const weeks = item.type === 'RENT' ? (item.rentWeeks || 1) : 1;
        return {
          ...item,
          quantity: newQuantity,
          price: item.unitPrice * weeks * newQuantity
        };
      }
      return item;
    }));
  };

  const handleUpdateRentWeeks = (itemId: string, newWeeks: number) => {
    if (newWeeks < 1) return;
    setCart(cart.map(item => {
      if (item.id === itemId && item.type === 'RENT') {
        return {
          ...item,
          rentWeeks: newWeeks,
          price: item.unitPrice * newWeeks * item.quantity
        };
      }
      return item;
    }));
  };

  const handlePlaceOrder = (address: any, paymentMethod: string) => {
    if (!user) {
      alert("Please login to complete purchase.");
      setShowAuthModal(true);
      return;
    }

    // Update User Profile with purchased/rented books
    const newBought = [...user.boughtBooks];
    const newRented = [...user.rentedBooks];

    cart.forEach(item => {
      if (item.type === 'BUY') newBought.push(item.bookId);
      else newRented.push(item.bookId);
    });

    const updatedUser = { ...user, boughtBooks: newBought, rentedBooks: newRented };
    setUser(updatedUser);

    // Attempt to update profile in Supabase
    // Note: We use snake_case for DB columns
    supabase.from('profiles').upsert({
      id: user.id,
      bought_books: newBought,
      rented_books: newRented
    }).then(({ error }) => {
      if (error) console.log("Profile update failed (table might not exist)", error);
    });

    setCart([]);
    setCurrentView(View.ORDER_SUCCESS);
  };

  const handleToggleFavorite = (bookId: string) => {
    if (!user) {
      setShowAuthModal(true);
      return;
    }

    const isFavorite = user.favoriteBooks.includes(bookId);
    let newFavorites;

    if (isFavorite) {
      newFavorites = user.favoriteBooks.filter(id => id !== bookId);
    } else {
      newFavorites = [...user.favoriteBooks, bookId];
    }

    setUser({ ...user, favoriteBooks: newFavorites });

    // Attempt DB update
    supabase.from('profiles').upsert({
      id: user.id,
      favorite_books: newFavorites
    }).then(({ error }) => {
       if (error) console.log("Fav update failed", error);
    });
  };

  const handleAddReview = async (bookId: string, review: Review) => {
    // Update local state first
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = [review, ...book.reviews];
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = Number((totalRating / newReviews.length).toFixed(1));

        const updatedBook = {
          ...book,
          reviews: newReviews,
          averageRating: avgRating
        };

        // Update Supabase
        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review DB save failed", error);
        });

        // Also update the currently selected book if it's open in details view
        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }

        return updatedBook;
      }
      return book;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      <Navbar
        currentView={currentView}
        setCurrentView={setCurrentView}
        user={user}
        onLoginClick={() => setShowAuthModal(true)}
        onLogoutClick={handleLogout}
        onPostBookClick={() => {
          if (!user) {
            setShowAuthModal(true);
          } else {
            setShowAddBookModal(true);
          }
        }}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
        cartItemCount={cart.length}
      />

      <main className="flex-grow container mx-auto px-4 py-8">
        {currentView === View.STORE && (
          <>
            <Hero />
            <BookStore
              books={books}
              user={user}
              onBookClick={(book) => {
                setSelectedBook(book);
                setCurrentView(View.BOOK_DETAILS);
              }}
              onToggleFavorite={handleToggleFavorite}
            />
          </>
        )}

        {currentView === View.BOOK_DETAILS && selectedBook && (
          <BookDetails 
            book={selectedBook} 
            user={user}
            onBack={() => {
              setSelectedBook(null);
              setCurrentView(View.STORE);
            }} 
            onAddToCart={handleAddToCart}
            onAddReview={handleAddReview}
          />
        )}

        {currentView === View.CART && (
          <Cart 
            items={cart} 
            onRemove={handleRemoveFromCart}
            onUpdateQuantity={handleUpdateQuantity}
            onUpdateRentWeeks={handleUpdateRentWeeks}
            onCheckout={() => {
              if (cart.length > 0) setCurrentView(View.CHECKOUT);
            }}
            onContinueShopping={() => setCurrentView(View.STORE)}
          />
        )}

        {currentView === View.CHECKOUT && (
          <Checkout 
            total={cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05)}
            onBack={() => setCurrentView(View.CART)}
            onPlaceOrder={handlePlaceOrder}
          />
        )}

        {currentView === View.ORDER_SUCCESS && (
          <OrderSuccess onContinue={() => setCurrentView(View.STORE)} />
        )}

        {currentView === View.CONTACT && (
          <Contact />
        )}

        {currentView === View.AI_HELPER && (
          <AIHelper />
        )}

        {currentView === View.COMMUNITY && (
          <Community user={user} />
        )}

        {currentView === View.PROFILE && user && (
          <Profile 
            user={user} 
            books={books} 
            onLogout={handleLogout} 
            onUpdateUser={handleUpdateUser}
            onBookClick={(book) => {
              setSelectedBook(book);
              setCurrentView(View.BOOK_DETAILS);
            }}
          />
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Book } from '../types';
import { X, Upload, IndianRupee, Loader2 } from 'lucide-react';

interface AddBookModalProps {
  onClose: () => void;
  onAddBook: (book: Book) => void;
}

const AddBookModal: React.FC<AddBookModalProps> = ({ onClose, onAddBook }) => {
  const [formData, setFormData] = useState({
    title: '',
    author: '',
    description: '',
    category: 'Engineering',
    priceBuy: '',
    priceRent: '',
  });

  const [previewImages, setPreviewImages] = useState<string[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const convertToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = error => reject(error);
    });
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setIsProcessing(true);
      try {
        const files = Array.from(e.target.files);
        const base64Promises = files.map(file => convertToBase64(file));
        const base64Images = await Promise.all(base64Promises);
        setPreviewImages(prev => [...prev, ...base64Images]);
      } catch (error) {
        console.error("Error converting images:", error);
        alert("Failed to process images.");
      } finally {
        setIsProcessing(false);
      }
    }
  };

  const removeImage = (index: number) => {
    setPreviewImages(prev => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newBook: Book = {
      id: Date.now().toString(),
      title: formData.title,
      author: formData.author,
      description: formData.description,
      category: formData.category,
      priceBuy: Number(formData.priceBuy),
      priceRent: Number(formData.priceRent),
      // Use the first uploaded image as main cover, or random fallback
      imageUrl: previewImages.length > 0 ? previewImages[0] : `https://picsum.photos/200/300?random=${Date.now()}`,
      images: previewImages,
      reviews: [],
      averageRating: 0,
    };
    onAddBook(newBook);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white dark:bg-bgDark w-full max-w-lg rounded-3xl p-8 relative shadow-2xl border border-gray-200 dark:border-primaryGreen/30 animate-in fade-in zoom-in duration-200 max-h-[90vh] overflow-y-auto custom-scrollbar">
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 dark:hover:text-cream transition-colors"
        >
          <X size={24} />
        </button>

        <h2 className="text-3xl font-serif font-bold mb-6 text-gray-900 dark:text-cream">
          Post a Book
        </h2>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Book Title</label>
            <input
              name="title"
              required
              value={formData.title}
              onChange={handleChange}
              className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors"
              placeholder="e.g. Clean Code"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Author</label>
            <input
              name="author"
              required
              value={formData.author}
              onChange={handleChange}
              className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors"
              placeholder="e.g. Robert C. Martin"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Category</label>
            <select
              name="category"
              value={formData.category}
              onChange={handleChange}
              className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors appearance-none"
            >
              <option>Engineering</option>
              <option>Medical</option>
              <option>Arts & Humanities</option>
              <option>Fiction</option>
              <option>Non-Fiction</option>
              <option>Competitive Exams</option>
            </select>
          </div>

          {/* Multiple Image Upload Section */}
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Book Images</label>

            {/* Image Previews */}
            {previewImages.length > 0 && (
              <div className="flex gap-3 overflow-x-auto mb-3 pb-2 scrollbar-thin scrollbar-thumb-gray-300 dark:scrollbar-thumb-gray-600">
                {previewImages.map((img, index) => (
                  <div key={index} className="relative w-20 h-28 flex-shrink-0 rounded-lg overflow-hidden border border-gray-200 dark:border-white/10 group bg-gray-100 dark:bg-bgDarker">
                    <img src={img} alt={`Preview ${index}`} className="w-full h-full object-cover" />
                    <button
                      type="button"
                      onClick={() => removeImage(index)}
                      className="absolute top-1 right-1 bg-red-500 hover:bg-red-600 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity shadow-md"
                    >
                      <X size={12} />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <label className={`flex flex-col items-center justify-center border-2 border-dashed border-gray-300 dark:border-white/10 rounded-xl cursor-pointer hover:border-primaryGreen hover:bg-primaryGreen/5 transition-all h-28 group ${isProcessing ? 'opacity-50 pointer-events-none' : ''}`}>
               <div className="text-center p-2 text-gray-500 dark:text-gray-400 group-hover:text-primaryGreen transition-colors">
                  {isProcessing ? (
                     <Loader2 size={24} className="mx-auto mb-2 animate-spin" />
                  ) : (
                     <Upload size={24} className="mx-auto mb-2" />
                  )}
                  <span className="text-sm font-medium">{isProcessing ? 'Processing...' : 'Click to upload images'}</span>
                  <p className="text-xs text-gray-400 mt-1">Select multiple files (JPG, PNG)</p>
               </div>
               <input 
                  type="file" 
                  className="hidden" 
                  accept="image/*" 
                  multiple 
                  onChange={handleImageUpload} 
                  disabled={isProcessing}
               />
            </label>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Buy Price (₹)</label>
              <div className="relative">
                <IndianRupee size={16} className="absolute left-3 top-3.5 text-gray-400" />
                <input
                  type="number"
                  name="priceBuy"
                  required
                  value={formData.priceBuy}
                  onChange={handleChange}
                  className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-9 pr-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors"
                  placeholder="0.00"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Rent Price (₹)</label>
              <div className="relative">
                <IndianRupee size={16} className="absolute left-3 top-3.5 text-gray-400" />
                <input
                  type="number"
                  name="priceRent"
                  required
                  value={formData.priceRent}
                  onChange={handleChange}
                  className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-9 pr-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors"
                  placeholder="0.00"
                />
              </div>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Description</label>
            <textarea
              name="description"
              required
              value={formData.description}
              onChange={handleChange}
              rows={3}
              className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors resize-none"
              placeholder="Describe the condition and contents..."
            />
          </div>

          <button
            type="submit"
            disabled={isProcessing}
            className="w-full bg-primaryGreen hover:bg-opacity-90 text-white font-bold py-3.5 rounded-xl shadow-lg shadow-primaryGreen/20 transition-all transform active:scale-95 mt-4 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Post Book Now
          </button>
        </form>
      </div>
    </div>
  );
};

