import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import BookStore from './components/BookStore';
import AIHelper from './components/AIHelper';
import Community from './components/Community';
import AuthModal from './components/Auth';
import AddBookModal from './components/AddBook';
import BookDetails from './components/BookDetails';
import Cart from './components/Cart';
import Checkout from './components/Checkout';
import OrderSuccess from './components/OrderSuccess';
import Contact from './components/Contact';
import Profile from './components/Profile';
import { View, User, Book, CartItem, Review } from './types';
import { supabase } from './lib/supabase';

// Mock Initial Data (Fallback) - Only used if DB is empty/fails
const INITIAL_BOOKS: Book[] = [];

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.STORE);
  const [user, setUser] = useState<User | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showAddBookModal, setShowAddBookModal] = useState(false);
  const [books, setBooks] = useState<Book[]>(INITIAL_BOOKS);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // New States for Shopping Flow
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);

  // --- Supabase Integration ---

  // 1. Check for active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        fetchUserProfile(session.user);
      }
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        fetchUserProfile(session.user);
      } else {
        setUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // 2. Fetch Books from Supabase
  useEffect(() => {
    const fetchBooks = async () => {
      try {
        const { data, error } = await supabase.from('books').select('*').order('id', { ascending: false });
        if (error) {
          console.log("Using local books (Supabase table 'books' not found or error):", error.message);
          return;
        }
        if (data && data.length > 0) {
          const mappedBooks: Book[] = data.map((b: any) => ({
            id: b.id,
            title: b.title,
            author: b.author,
            description: b.description,
            category: b.category,
            priceBuy: b.price_buy || b.priceBuy,
            priceRent: b.price_rent || b.priceRent,
            imageUrl: b.image_url || b.imageUrl,
            images: b.images || [],
            reviews: b.reviews || [],
            averageRating: b.average_rating || b.averageRating || 0,
            ownerId: b.owner_id
          }));
          setBooks(mappedBooks);
        }
      } catch (err) {
        console.error("Error connecting to DB:", err);
      }
    };
    fetchBooks();
  }, []);

  const fetchUserProfile = async (authUser: any) => {
    // Try to get profile from 'profiles' table
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .single();

      if (data && !error) {
        setUser({
          id: data.id,
          name: data.name || authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: data.avatar || authUser.user_metadata?.avatar_url,
          rentedBooks: data.rented_books || [],
          boughtBooks: data.bought_books || [],
          favoriteBooks: data.favorite_books || [],
          listedBooks: data.listed_books || [],
        });
      } else {
        // Fallback if profile table doesn't exist yet
        setUser({
          id: authUser.id,
          name: authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: authUser.user_metadata?.avatar_url,
          rentedBooks: [],
          boughtBooks: [],
          favoriteBooks: [],
          listedBooks: [],
        });
      }
    } catch (error) {
       // Fallback on error
       setUser({
        id: authUser.id,
        name: authUser.user_metadata?.full_name || 'User',
        email: authUser.email,
        avatar: authUser.user_metadata?.avatar_url,
        rentedBooks: [],
        boughtBooks: [],
        favoriteBooks: [],
        listedBooks: [],
      });
    }
  };

  // --- End Supabase Integration ---

  // Toggle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setCurrentView(View.STORE);
  };

  const handleUpdateUser = async (updatedUser: User) => {
    setUser(updatedUser);

    // Persist to Supabase
    try {
      const { error } = await supabase.from('profiles').upsert({
        id: updatedUser.id,
        name: updatedUser.name,
        email: updatedUser.email,
        avatar: updatedUser.avatar,
        rented_books: updatedUser.rentedBooks,
        bought_books: updatedUser.boughtBooks,
        favorite_books: updatedUser.favoriteBooks,
        listed_books: updatedUser.listedBooks
      });

      if (error) {
        console.error("Failed to update profile:", error.message);
      }
    } catch (err) {
      console.error("Error updating user profile:", err);
    }
  };

  const handleAddBook = async (newBook: Book) => {
    // Check auth
    if (!user) {
        setShowAuthModal(true);
        return;
    }

    const bookWithOwner = { ...newBook, ownerId: user.id };

    // Optimistic Update
    setBooks([bookWithOwner, ...books]);
    const updatedUser = { ...user, listedBooks: [newBook.id, ...user.listedBooks] };
    setUser(updatedUser);
    handleUpdateUser(updatedUser);

    // Attempt to save to Supabase
    try {
      const dbBook = {
        // Ensure ID is not sent if Supabase auto-generates (UUID), 
        // but here we are using Date.now() strings from modal.
        // Ideally, we let Supabase generate UUID, but we will stick to client ID for this flow
        // or ensure DB accepts text id.
        id: newBook.id, 
        title: newBook.title,
        author: newBook.author,
        description: newBook.description,
        category: newBook.category,
        price_buy: newBook.priceBuy,
        price_rent: newBook.priceRent,
        image_url: newBook.imageUrl,
        images: newBook.images,
        average_rating: newBook.averageRating,
        reviews: newBook.reviews,
        owner_id: user.id // Save the user ID
      };

      const { error } = await supabase.from('books').insert([dbBook]);
      if (error) console.error("Error saving book to DB:", error.message);
    } catch (e) {
      console.error("Failed to save book to Supabase");
    }

    setShowAddBookModal(false);
    setCurrentView(View.STORE);
  };

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Cart Functions
  const handleAddToCart = (item: CartItem) => {
    setCart([...cart, item]);
    alert(`${item.title} added to cart!`);
  };

  const handleRemoveFromCart = (itemId: string) => {
    setCart(cart.filter(item => item.id !== itemId));
  };

  const handleUpdateQuantity = (itemId: string, newQuantity: number) => {
    if (newQuantity < 1) return;
    setCart(cart.map(item => {
      if (item.id === itemId) {
        const weeks = item.type === 'RENT' ? (item.rentWeeks || 1) : 1;
        return {
          ...item,
          quantity: newQuantity,
          price: item.unitPrice * weeks * newQuantity
        };
      }
      return item;
    }));
  };

  const handleUpdateRentWeeks = (itemId: string, newWeeks: number) => {
    if (newWeeks < 1) return;
    setCart(cart.map(item => {
      if (item.id === itemId && item.type === 'RENT') {
        return {
          ...item,
          rentWeeks: newWeeks,
          price: item.unitPrice * newWeeks * item.quantity
        };
      }
      return item;
    }));
  };

  const handlePlaceOrder = (address: any, paymentMethod: string) => {
    if (!user) {
      alert("Please login to complete purchase.");
      setShowAuthModal(true);
      return;
    }

    // Update User Profile with purchased/rented books
    const newBought = [...user.boughtBooks];
    const newRented = [...user.rentedBooks];

    cart.forEach(item => {
      if (item.type === 'BUY') newBought.push(item.bookId);
      else newRented.push(item.bookId);
    });

    const updatedUser = { ...user, boughtBooks: newBought, rentedBooks: newRented };
    // handleUpdateUser takes care of both local state and Supabase persistence
    handleUpdateUser(updatedUser);

    setCart([]);
    setCurrentView(View.ORDER_SUCCESS);
  };

  const handleToggleFavorite = (bookId: string) => {
    if (!user) {
      setShowAuthModal(true);
      return;
    }

    const isFavorite = user.favoriteBooks.includes(bookId);
    let newFavorites;

    if (isFavorite) {
      newFavorites = user.favoriteBooks.filter(id => id !== bookId);
    } else {
      newFavorites = [...user.favoriteBooks, bookId];
    }

    const updatedUser = { ...user, favoriteBooks: newFavorites };
    handleUpdateUser(updatedUser);
  };

  const handleAddReview = async (bookId: string, review: Review) => {
    // Update local state first
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = [review, ...book.reviews];
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = Number((totalRating / newReviews.length).toFixed(1));

        const updatedBook = {
          ...book,
          reviews: newReviews,
          averageRating: avgRating
        };

        // Update Supabase
        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review DB save failed", error);
        });

        // Also update the currently selected book if it's open in details view
        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }

        return updatedBook;
      }
      return book;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      <Navbar
        currentView={currentView}
        setCurrentView={setCurrentView}
        user={user}
        onLoginClick={() => setShowAuthModal(true)}
        onLogoutClick={handleLogout}
        onPostBookClick={() => {
          if (!user) {
            setShowAuthModal(true);
          } else {
            setShowAddBookModal(true);
          }
        }}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
        cartItemCount={cart.length}
      />

      <main className="flex-grow container mx-auto px-4 py-8">
        {currentView === View.STORE && (
          <>
            <Hero />
            <BookStore
              books={books}
              user={user}
              onBookClick={(book) => {
                setSelectedBook(book);
                setCurrentView(View.BOOK_DETAILS);
              }}
              onToggleFavorite={handleToggleFavorite}
            />
          </>
        )}

        {currentView === View.BOOK_DETAILS && selectedBook && (
          <BookDetails 
            book={selectedBook} 
            user={user}
            onBack={() => {
              setSelectedBook(null);
              setCurrentView(View.STORE);
            }} 
            onAddToCart={handleAddToCart}
            onAddReview={handleAddReview}
          />
        )}

        {currentView === View.CART && (
          <Cart 
            items={cart} 
            onRemove={handleRemoveFromCart}
            onUpdateQuantity={handleUpdateQuantity}
            onUpdateRentWeeks={handleUpdateRentWeeks}
            onCheckout={() => {
              if (cart.length > 0) setCurrentView(View.CHECKOUT);
            }}
            onContinueShopping={() => setCurrentView(View.STORE)}
          />
        )}

        {currentView === View.CHECKOUT && (
          <Checkout 
            total={cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05)}
            onBack={() => setCurrentView(View.CART)}
            onPlaceOrder={handlePlaceOrder}
          />
        )}

        {currentView === View.ORDER_SUCCESS && (
          <OrderSuccess onContinue={() => setCurrentView(View.STORE)} />
        )}

        {currentView === View.CONTACT && (
          <Contact />
        )}

        {currentView === View.AI_HELPER && (
          <AIHelper />
        )}

        {currentView === View.COMMUNITY && (
          <Community user={user} />
        )}

        {currentView === View.PROFILE && user && (
          <Profile 
            user={user} 
            books={books} 
            onLogout={handleLogout} 
            onUpdateUser={handleUpdateUser}
            onBookClick={(book) => {
              setSelectedBook(book);
              setCurrentView(View.BOOK_DETAILS);
            }}
          />
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, ForumPost, ForumReply } from '../types';
import { MessageSquare, Heart, Share2, Send, Plus, Search, User as UserIcon, X, Copy, Facebook, Twitter, MessageCircle, Loader2 } from 'lucide-react';
import { supabase } from '../lib/supabase';

interface CommunityProps {
  user: User | null;
}

const CATEGORIES = [
  'All',
  'Competitive Exams',
  'College Subjects',
  'Book Reviews',
  'Study Tips',
  'Exam Guidance',
  'Recommendations'
];

const TRENDING_TAGS = ['#JEE2024', '#NEETPREP', '#UPSC2025', '#PYTHONNOTES', '#BOOKCLUB'];

const Community: React.FC<CommunityProps> = ({ user }) => {
  const [posts, setPosts] = useState<ForumPost[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [isAskModalOpen, setIsAskModalOpen] = useState(false);
  const [replyText, setReplyText] = useState<{[key: string]: string}>({});
  const [expandedPostId, setExpandedPostId] = useState<string | null>(null);

  // Share Modal State
  const [sharePost, setSharePost] = useState<ForumPost | null>(null);

  // New Post Form State
  const [newPostTitle, setNewPostTitle] = useState('');
  const [newPostContent, setNewPostContent] = useState('');
  const [newPostCategory, setNewPostCategory] = useState(CATEGORIES[1]);
  const [isPosting, setIsPosting] = useState(false);

  // Fetch Posts from Supabase
  const fetchPosts = async () => {
    try {
      const { data: postsData, error: postsError } = await supabase
        .from('forum_posts')
        .select(`
          *,
          forum_replies (*)
        `)
        .order('created_at', { ascending: false });

      if (postsError) throw postsError;

      if (postsData) {
        const mappedPosts: ForumPost[] = postsData.map((p: any) => ({
          id: p.id,
          authorId: p.author_id,
          authorName: p.author_name || 'Anonymous',
          title: p.title,
          content: p.content,
          category: p.category,
          likedBy: p.liked_by || [],
          tags: p.tags || [],
          timestamp: new Date(p.created_at).toLocaleDateString(),
          replies: (p.forum_replies || []).map((r: any) => ({
             id: r.id,
             postId: r.post_id,
             authorId: r.author_id,
             authorName: r.author_name || 'Anonymous',
             content: r.content,
             likedBy: r.liked_by || [],
             timestamp: new Date(r.created_at).toLocaleDateString()
          }))
        }));
        setPosts(mappedPosts);
      }
    } catch (error) {
      console.error("Error fetching community posts:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  const filteredPosts = selectedCategory === 'All' 
    ? posts 
    : posts.filter(post => post.category === selectedCategory);

  const handleLikePost = async (postId: string) => {
    if (!user) {
      alert("Please login to like posts.");
      return;
    }

    const postToUpdate = posts.find(p => p.id === postId);
    if (!postToUpdate) return;

    const isLiked = postToUpdate.likedBy.includes(user.id);
    const newLikedBy = isLiked
      ? postToUpdate.likedBy.filter(id => id !== user.id)
      : [...postToUpdate.likedBy, user.id];

    // Optimistic Update
    setPosts(posts.map(post => 
      post.id === postId ? { ...post, likedBy: newLikedBy } : post
    ));

    // DB Update
    await supabase
      .from('forum_posts')
      .update({ liked_by: newLikedBy })
      .eq('id', postId);
  };

  const handleLikeReply = async (postId: string, replyId: string) => {
    if (!user) {
      alert("Please login to like replies.");
      return;
    }

    const post = posts.find(p => p.id === postId);
    if (!post) return;
    const reply = post.replies.find(r => r.id === replyId);
    if (!reply) return;

    const isLiked = reply.likedBy.includes(user.id);
    const newLikedBy = isLiked
      ? reply.likedBy.filter(id => id !== user.id)
      : [...reply.likedBy, user.id];

    // Optimistic Update
    setPosts(posts.map(p => {
      if (p.id === postId) {
        return {
          ...p,
          replies: p.replies.map(r => r.id === replyId ? { ...r, likedBy: newLikedBy } : r)
        };
      }
      return p;
    }));

    // DB Update
    await supabase
      .from('forum_replies')
      .update({ liked_by: newLikedBy })
      .eq('id', replyId);
  };

  const executeShare = (platform: string) => {
    if (!sharePost) return;

    const text = `Check out "${sharePost.title}" on Bookgram!\n${sharePost.content.substring(0, 100)}...`;
    const url = "https://bookgram.demo/post/" + sharePost.id; // Demo URL
    const encodedText = encodeURIComponent(text);
    const encodedUrl = encodeURIComponent(url);

    switch (platform) {
      case 'whatsapp':
        window.open(`https://wa.me/?text=${encodedText} ${encodedUrl}`, '_blank');
        break;
      case 'facebook':
        window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`, '_blank');
        break;
      case 'x':
        window.open(`https://twitter.com/intent/tweet?text=${encodedText}&url=${encodedUrl}`, '_blank');
        break;
      case 'message':
        window.location.href = `sms:?body=${encodedText} ${encodedUrl}`;
        break;
      case 'copy':
        navigator.clipboard.writeText(`${text}\n${url}`);
        alert('Copied to clipboard!');
        break;
    }
    setSharePost(null);
  };

  const handleSubmitReply = async (postId: string) => {
    if (!user) {
      alert("Please login to reply.");
      return;
    }
    const text = replyText[postId];
    if (!text?.trim()) return;

    // Insert into DB
    const { data, error } = await supabase.from('forum_replies').insert([{
      post_id: postId,
      author_id: user.id,
      author_name: user.name,
      content: text,
      liked_by: []
    }]).select().single();

    if (error) {
      console.error("Error submitting reply:", error);
      return;
    }

    if (data) {
       const newReply: ForumReply = {
         id: data.id,
         postId: postId,
         authorId: user.id,
         authorName: user.name,
         content: text,
         likedBy: [],
         timestamp: 'Just now'
       };

       setPosts(posts.map(post => 
         post.id === postId ? { ...post, replies: [...post.replies, newReply] } : post
       ));
       setReplyText({ ...replyText, [postId]: '' });
    }
  };

  const handleSubmitQuestion = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) {
      alert("Please login to post a question.");
      return;
    }
    setIsPosting(true);

    try {
      const { data, error } = await supabase.from('forum_posts').insert([{
        author_id: user.id,
        author_name: user.name,
        title: newPostTitle,
        content: newPostContent,
        category: newPostCategory,
        liked_by: [],
        tags: [] 
      }]).select().single();

      if (error) throw error;

      if (data) {
        const newPost: ForumPost = {
          id: data.id,
          authorId: user.id,
          authorName: user.name,
          title: newPostTitle,
          content: newPostContent,
          category: newPostCategory,
          likedBy: [],
          replies: [],
          timestamp: 'Just now',
          tags: []
        };
        setPosts([newPost, ...posts]);
        setIsAskModalOpen(false);
        setNewPostTitle('');
        setNewPostContent('');
        setSelectedCategory('All');
      }
    } catch (err) {
      console.error("Error creating post:", err);
      alert("Failed to post question.");
    } finally {
      setIsPosting(false);
    }
  };

  if (loading) {
    return (
       <div className="flex justify-center items-center h-64">
          <Loader2 className="animate-spin text-primaryGreen" size={48} />
       </div>
    );
  }

  return (
    <div className="flex flex-col md:flex-row gap-8 pb-12">
      {/* Sidebar Categories */}
      <div className="w-full md:w-64 flex-shrink-0">
        <div className="sticky top-24">
          <h3 className="text-xl font-serif font-bold mb-4 text-gray-800 dark:text-cream px-2">Categories</h3>
          <div className="space-y-1">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`w-full text-left px-4 py-3 rounded-xl text-sm font-medium transition-colors ${
                  selectedCategory === cat
                    ? 'bg-primaryGreen text-white shadow-lg shadow-primaryGreen/20'
                    : 'text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-white/5'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Main Feed */}
      <div className="flex-grow space-y-6">
        {/* Header Section */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-2">
          <div>
            <h2 className="text-3xl font-serif font-bold text-gray-900 dark:text-cream">Community Forum</h2>
            <p className="text-gray-500 dark:text-gray-400 text-sm">Ask questions, share notes, and connect with fellow students.</p>
          </div>
          <button
            onClick={() => {
              if (user) setIsAskModalOpen(true);
              else alert("Please login to ask a question.");
            }}
            className="bg-primaryGreen text-white px-6 py-3 rounded-xl font-semibold shadow-lg shadow-primaryGreen/20 hover:scale-105 transition-transform flex items-center gap-2 w-fit"
          >
            <Plus size={20} /> Ask Question
          </button>
        </div>

        {/* Trending Tags Banner */}
        <div className="bg-[#3d2b2b] dark:bg-[#2a1f1f] rounded-2xl p-6 text-white shadow-lg relative overflow-hidden">
           <div className="absolute -top-10 -right-10 w-32 h-32 bg-white/5 rounded-full blur-2xl"></div>
           <h3 className="text-lg font-bold mb-3 flex items-center gap-2">
             Trending #Tags
           </h3>
           <div className="flex flex-wrap gap-2">
             {TRENDING_TAGS.map(tag => (
