import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import BookStore from './components/BookStore';
import AIHelper from './components/AIHelper';
import Community from './components/Community';
import AuthModal from './components/Auth';
import AddBookModal from './components/AddBook';
import BookDetails from './components/BookDetails';
import Cart from './components/Cart';
import Checkout from './components/Checkout';
import OrderSuccess from './components/OrderSuccess';
import Contact from './components/Contact';
import Profile from './components/Profile';
import { View, User, Book, CartItem, Review } from './types';
import { supabase } from './lib/supabase';

// Mock Initial Data (Fallback) - Only used if DB is empty/fails
const INITIAL_BOOKS: Book[] = [];

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.STORE);
  const [user, setUser] = useState<User | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showAddBookModal, setShowAddBookModal] = useState(false);
  const [books, setBooks] = useState<Book[]>(INITIAL_BOOKS);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // New States for Shopping Flow
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);

  // --- Supabase Integration ---

  // 1. Check for active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session) {
        fetchUserProfile(session.user);
      }
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        fetchUserProfile(session.user);
      } else {
        setUser(null);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // 2. Fetch Books from Supabase
  useEffect(() => {
    const fetchBooks = async () => {
      try {
        const { data, error } = await supabase.from('books').select('*').order('id', { ascending: false });
        if (error) {
          console.log("Using local books (Supabase table 'books' not found or error):", error.message);
          return;
        }
        if (data && data.length > 0) {
          const mappedBooks: Book[] = data.map((b: any) => ({
            id: b.id,
            title: b.title,
            author: b.author,
            description: b.description,
            category: b.category,
            priceBuy: b.price_buy || b.priceBuy,
            priceRent: b.price_rent || b.priceRent,
            imageUrl: b.image_url || b.imageUrl,
            images: b.images || [],
            reviews: b.reviews || [],
            averageRating: b.average_rating || b.averageRating || 0,
            ownerId: b.owner_id
          }));
          setBooks(mappedBooks);
        }
      } catch (err) {
        console.error("Error connecting to DB:", err);
      }
    };
    fetchBooks();
  }, []);

  const fetchUserProfile = async (authUser: any) => {
    // Try to get profile from 'profiles' table
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .single();

      if (data && !error) {
        setUser({
          id: data.id,
          name: data.name || authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: data.avatar || authUser.user_metadata?.avatar_url,
          rentedBooks: data.rented_books || [],
          boughtBooks: data.bought_books || [],
          favoriteBooks: data.favorite_books || [],
          listedBooks: data.listed_books || [],
        });
      } else {
        // Fallback if profile table doesn't exist yet
        setUser({
          id: authUser.id,
          name: authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: authUser.user_metadata?.avatar_url,
          rentedBooks: [],
          boughtBooks: [],
          favoriteBooks: [],
          listedBooks: [],
        });
      }
    } catch (error) {
       // Fallback on error
       setUser({
        id: authUser.id,
        name: authUser.user_metadata?.full_name || 'User',
        email: authUser.email,
        avatar: authUser.user_metadata?.avatar_url,
        rentedBooks: [],
        boughtBooks: [],
        favoriteBooks: [],
        listedBooks: [],
      });
    }
  };

  // --- End Supabase Integration ---

  // Toggle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setCurrentView(View.STORE);
  };

  const handleUpdateUser = async (updatedUser: User) => {
    setUser(updatedUser);

    // Persist to Supabase
    try {
      const { error } = await supabase.from('profiles').upsert({
        id: updatedUser.id,
        name: updatedUser.name,
        email: updatedUser.email,
        avatar: updatedUser.avatar,
        rented_books: updatedUser.rentedBooks,
        bought_books: updatedUser.boughtBooks,
        favorite_books: updatedUser.favoriteBooks,
        listed_books: updatedUser.listedBooks
      });

      if (error) {
        console.error("Failed to update profile:", error.message);
      }
    } catch (err) {
      console.error("Error updating user profile:", err);
    }
  };

  const handleAddBook = async (newBook: Book) => {
    // Check auth
    if (!user) {
        setShowAuthModal(true);
        return;
    }

    const bookWithOwner = { ...newBook, ownerId: user.id };

    // Optimistic Update
    setBooks([bookWithOwner, ...books]);
    const updatedUser = { ...user, listedBooks: [newBook.id, ...user.listedBooks] };
    setUser(updatedUser);
    handleUpdateUser(updatedUser);

    // Attempt to save to Supabase
    try {
      const dbBook = {
        // Ensure ID is not sent if Supabase auto-generates (UUID), 
        // but here we are using Date.now() strings from modal.
        // Ideally, we let Supabase generate UUID, but we will stick to client ID for this flow
        // or ensure DB accepts text id.
        id: newBook.id, 
        title: newBook.title,
        author: newBook.author,
        description: newBook.description,
        category: newBook.category,
        price_buy: newBook.priceBuy,
        price_rent: newBook.priceRent,
        image_url: newBook.imageUrl,
        images: newBook.images,
        average_rating: newBook.averageRating,
        reviews: newBook.reviews,
        owner_id: user.id // Save the user ID
      };

      const { error } = await supabase.from('books').insert([dbBook]);
      if (error) console.error("Error saving book to DB:", error.message);
    } catch (e) {
      console.error("Failed to save book to Supabase");
    }

    setShowAddBookModal(false);
    setCurrentView(View.STORE);
  };

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Cart Functions
  const handleAddToCart = (item: CartItem) => {
    setCart([...cart, item]);
    alert(`${item.title} added to cart!`);
  };

  const handleRemoveFromCart = (itemId: string) => {
    setCart(cart.filter(item => item.id !== itemId));
  };

  const handleUpdateQuantity = (itemId: string, newQuantity: number) => {
    if (newQuantity < 1) return;
    setCart(cart.map(item => {
      if (item.id === itemId) {
        const weeks = item.type === 'RENT' ? (item.rentWeeks || 1) : 1;
        return {
          ...item,
          quantity: newQuantity,
          price: item.unitPrice * weeks * newQuantity
        };
      }
      return item;
    }));
  };

  const handleUpdateRentWeeks = (itemId: string, newWeeks: number) => {
    if (newWeeks < 1) return;
    setCart(cart.map(item => {
      if (item.id === itemId && item.type === 'RENT') {
        return {
          ...item,
          rentWeeks: newWeeks,
          price: item.unitPrice * newWeeks * item.quantity
        };
      }
      return item;
    }));
  };

  const handlePlaceOrder = (address: any, paymentMethod: string) => {
    if (!user) {
      alert("Please login to complete purchase.");
      setShowAuthModal(true);
      return;
    }

    // Update User Profile with purchased/rented books
    const newBought = [...user.boughtBooks];
    const newRented = [...user.rentedBooks];

    cart.forEach(item => {
      if (item.type === 'BUY') newBought.push(item.bookId);
      else newRented.push(item.bookId);
    });

    const updatedUser = { ...user, boughtBooks: newBought, rentedBooks: newRented };
    // handleUpdateUser takes care of both local state and Supabase persistence
    handleUpdateUser(updatedUser);

    setCart([]);
    setCurrentView(View.ORDER_SUCCESS);
  };

  const handleToggleFavorite = (bookId: string) => {
    if (!user) {
      setShowAuthModal(true);
      return;
    }

    const isFavorite = user.favoriteBooks.includes(bookId);
    let newFavorites;

    if (isFavorite) {
      newFavorites = user.favoriteBooks.filter(id => id !== bookId);
    } else {
      newFavorites = [...user.favoriteBooks, bookId];
    }

    const updatedUser = { ...user, favoriteBooks: newFavorites };
    handleUpdateUser(updatedUser);
  };

  const handleAddReview = async (bookId: string, review: Review) => {
    // Update local state first
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = [review, ...book.reviews];
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = Number((totalRating / newReviews.length).toFixed(1));

        const updatedBook = {
          ...book,
          reviews: newReviews,
          averageRating: avgRating
        };

        // Update Supabase
        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review DB save failed", error);
        });

        // Also update the currently selected book if it's open in details view
        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }

        return updatedBook;
      }
      return book;
    }));
  };

  const handleEditReview = async (bookId: string, updatedReview: Review) => {
    // Update local state first
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = book.reviews.map(r => r.userId === updatedReview.userId ? updatedReview : r);
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = newReviews.length > 0 ? Number((totalRating / newReviews.length).toFixed(1)) : 0;

        const updatedBook = {
          ...book,
          reviews: newReviews,
          averageRating: avgRating
        };

        // Update Supabase
        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review update DB save failed", error);
        });

        // Also update the currently selected book if it's open in details view
        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }

        return updatedBook;
      }
      return book;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      <Navbar
        currentView={currentView}
        setCurrentView={setCurrentView}
        user={user}
        onLoginClick={() => setShowAuthModal(true)}
        onLogoutClick={handleLogout}
        onPostBookClick={() => {
          if (!user) {
            setShowAuthModal(true);
          } else {
            setShowAddBookModal(true);
          }
        }}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
        cartItemCount={cart.length}
      />

      <main className="flex-grow container mx-auto px-4 py-8">
        {currentView === View.STORE && (
          <>
            <Hero />
            <BookStore
              books={books}
              user={user}
              onBookClick={(book) => {
                setSelectedBook(book);
                setCurrentView(View.BOOK_DETAILS);
              }}
              onToggleFavorite={handleToggleFavorite}
            />
          </>
        )}

        {currentView === View.BOOK_DETAILS && selectedBook && (
          <BookDetails 
            book={selectedBook} 
            user={user}
            onBack={() => {
              setSelectedBook(null);
              setCurrentView(View.STORE);
            }} 
            onAddToCart={handleAddToCart}
            onAddReview={handleAddReview}
            onEditReview={handleEditReview}
          />
        )}

        {currentView === View.CART && (
          <Cart 
            items={cart} 
            onRemove={handleRemoveFromCart}
            onUpdateQuantity={handleUpdateQuantity}
            onUpdateRentWeeks={handleUpdateRentWeeks}
            onCheckout={() => {
              if (cart.length > 0) setCurrentView(View.CHECKOUT);
            }}
            onContinueShopping={() => setCurrentView(View.STORE)}
          />
        )}

        {currentView === View.CHECKOUT && (
          <Checkout 
            total={cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05)}
            onBack={() => setCurrentView(View.CART)}
            onPlaceOrder={handlePlaceOrder}
          />
        )}

        {currentView === View.ORDER_SUCCESS && (
          <OrderSuccess onContinue={() => setCurrentView(View.STORE)} />
        )}

        {currentView === View.CONTACT && (
          <Contact />
        )}

        {currentView === View.AI_HELPER && (
          <AIHelper />
        )}

        {currentView === View.COMMUNITY && (
          <Community user={user} />
        )}

        {currentView === View.PROFILE && user && (
          <Profile 
            user={user} 
            books={books} 
            onLogout={handleLogout} 
            onUpdateUser={handleUpdateUser}
            onBookClick={(book) => {
              setSelectedBook(book);
              setCurrentView(View.BOOK_DETAILS);
            }}
          />
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Book, CartItem, User, Review } from '../types';
import { ChevronLeft, ShoppingBag, Clock, IndianRupee, Star, User as UserIcon, Send, PenLine } from 'lucide-react';

interface BookDetailsProps {
  book: Book;
  user: User | null;
  onBack: () => void;
  onAddToCart: (item: CartItem) => void;
  onAddReview: (bookId: string, review: Review) => void;
  onEditReview: (bookId: string, review: Review) => void;
}

const BookDetails: React.FC<BookDetailsProps> = ({ book, user, onBack, onAddToCart, onAddReview, onEditReview }) => {
  const [rentWeeks, setRentWeeks] = useState(1);
  const [mode, setMode] = useState<'BUY' | 'RENT'>('RENT');

  // Check if user has already reviewed
  const existingReview = user ? book.reviews.find(r => r.userId === user.id) : undefined;

  // Review State
  const [rating, setRating] = useState(0);
  const [hoverRating, setHoverRating] = useState(0);
  const [reviewComment, setReviewComment] = useState('');

  // Populate form if review exists
  useEffect(() => {
    if (existingReview) {
      setRating(existingReview.rating);
      setReviewComment(existingReview.comment);
    } else {
      setRating(0);
      setReviewComment('');
    }
  }, [existingReview]);

  const handleAddToCart = () => {
    const unitPrice = mode === 'BUY' ? book.priceBuy : book.priceRent;
    const price = mode === 'BUY' ? unitPrice : unitPrice * rentWeeks;

    const cartItem: CartItem = {
      id: Date.now().toString(),
      bookId: book.id,
      title: book.title,
      author: book.author,
      imageUrl: book.imageUrl,
      type: mode,
      rentWeeks: mode === 'RENT' ? rentWeeks : undefined,
      price: price,
      quantity: 1,
      unitPrice: unitPrice
    };

    onAddToCart(cartItem);
    onBack();
  };

  const handleSubmitReview = (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) {
      alert("Please login to write a review.");
      return;
    }
    if (rating === 0) {
      alert("Please select a star rating.");
      return;
    }

    const reviewData: Review = {
      id: existingReview ? existingReview.id : Date.now().toString(),
      userId: user.id,
      userName: user.name,
      rating: rating,
      comment: reviewComment,
      timestamp: existingReview ? 'Edited just now' : 'Just now'
    };

    if (existingReview) {
      onEditReview(book.id, reviewData);
      alert("Review updated successfully!");
    } else {
      onAddReview(book.id, reviewData);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500 pb-12">
      <button 
        onClick={onBack}
        className="mb-6 flex items-center gap-2 text-gray-600 dark:text-gray-300 hover:text-primaryGreen transition-colors font-medium"
      >
        <ChevronLeft size={20} /> Back to Store
      </button>

      <div className="bg-white dark:bg-bgDark rounded-[2.5rem] overflow-hidden shadow-2xl border border-gray-100 dark:border-white/5 flex flex-col md:flex-row min-h-[500px] mb-12">

        {/* Image Section */}
        <div className="w-full md:w-1/2 bg-gray-100 dark:bg-bgDarker relative group">
           <img 
            src={book.imageUrl} 
            alt={book.title} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105"
           />
           <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-end p-8">
             <div className="text-white">
               <p className="font-bold text-lg">Category: {book.category}</p>
             </div>
           </div>
        </div>

        {/* Details Section */}
        <div className="w-full md:w-1/2 p-8 md:p-12 flex flex-col">
          <div className="mb-6">
            <span className="text-primaryGreen font-bold text-sm tracking-[0.2em] uppercase">{book.category}</span>
            <h1 className="text-4xl md:text-5xl font-serif font-bold text-gray-900 dark:text-cream mt-4 leading-tight">
              {book.title}
            </h1>
            <p className="text-xl text-gray-500 dark:text-gray-400 mt-2 font-medium">{book.author}</p>

            {/* Rating Display */}
            <div className="flex items-center gap-2 mt-4">
               <div className="flex text-yellow-400">
                  {[1,2,3,4,5].map(star => (
                    <Star key={star} size={20} className={star <= Math.round(book.averageRating) ? 'fill-current' : 'text-gray-300 dark:text-gray-700'} />
                  ))}
               </div>
               <span className="font-bold text-lg text-gray-700 dark:text-gray-300">{book.averageRating}</span>
               <span className="text-gray-500 dark:text-gray-500 text-sm">({book.reviews.length} reviews)</span>
            </div>
          </div>

          <div className="prose dark:prose-invert max-w-none mb-10">
            <p className="text-gray-600 dark:text-gray-300 leading-relaxed text-lg">
              {book.description}
            </p>
          </div>

          <div className="mt-auto space-y-8 bg-gray-50 dark:bg-white/5 p-8 rounded-3xl border border-gray-100 dark:border-white/5">
            {/* Toggle Mode */}
            <div className="bg-white dark:bg-bgDarker p-1.5 rounded-2xl flex relative shadow-sm border border-gray-100 dark:border-white/5">
               <div 
                 className={`absolute top-1.5 bottom-1.5 w-[calc(50%-6px)] bg-primaryGreen rounded-xl shadow-md transition-all duration-300 ${mode === 'BUY' ? 'left-1.5' : 'left-[50%]'}`}
               />
               <button 
                 onClick={() => setMode('BUY')}
                 className={`flex-1 relative z-10 py-3 text-center font-bold text-lg transition-colors ${mode === 'BUY' ? 'text-white' : 'text-gray-500 dark:text-gray-400'}`}
               >
                 Buy <span className="text-sm opacity-80">(₹{book.priceBuy})</span>
               </button>
               <button 
                 onClick={() => setMode('RENT')}
                 className={`flex-1 relative z-10 py-3 text-center font-bold text-lg transition-colors ${mode === 'RENT' ? 'text-white' : 'text-gray-500 dark:text-gray-400'}`}
               >
                 Rent <span className="text-sm opacity-80">(₹{book.priceRent}/wk)</span>
               </button>
            </div>

            {/* Rent Logic */}
            {mode === 'RENT' && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-300">
                 <div className="flex items-center justify-between mb-4">
                    <label className="font-medium text-gray-700 dark:text-gray-300 flex items-center gap-2 text-lg">
                      <Clock size={20} className="text-primaryGreen" /> Rent Duration
                    </label>
                    <div className="flex items-center gap-4 bg-white dark:bg-bgDarker rounded-xl p-1 border border-gray-200 dark:border-white/10">
                       <button 
                         onClick={() => setRentWeeks(Math.max(1, rentWeeks - 1))}
                         className="w-10 h-10 rounded-lg hover:bg-gray-100 dark:hover:bg-white/10 flex items-center justify-center font-bold text-xl"
                       >-</button>
                       <span className="font-bold w-16 text-center text-lg">{rentWeeks} wk</span>
                       <button 
                         onClick={() => setRentWeeks(rentWeeks + 1)}
                         className="w-10 h-10 rounded-lg hover:bg-gray-100 dark:hover:bg-white/10 flex items-center justify-center font-bold text-xl"
                       >+</button>
                    </div>
                 </div>
                 <div className="flex items-center justify-between pt-4 border-t border-gray-200 dark:border-white/10">
                    <span className="text-gray-500 font-medium">Total Rent Price</span>
                    <span className="text-3xl font-serif font-bold text-primaryGreen flex items-center">
                      <IndianRupee size={24} strokeWidth={3} />{book.priceRent * rentWeeks}
                    </span>
                 </div>
              </div>
            )}

            {/* Total Price for Buy */}
            {mode === 'BUY' && (
              <div className="flex items-center justify-between pt-2 animate-in fade-in slide-in-from-top-2 duration-300">
                  <span className="text-gray-700 dark:text-gray-300 font-medium text-lg">Purchase Price</span>
                  <span className="text-3xl font-serif font-bold text-gray-900 dark:text-cream flex items-center">
                    <IndianRupee size={24} strokeWidth={3} />{book.priceBuy}
                  </span>
              </div>
            )}

            <button
              onClick={handleAddToCart}
              className="w-full bg-primaryGreen hover:bg-[#466a32] text-white font-bold py-5 rounded-2xl shadow-xl shadow-primaryGreen/20 flex items-center justify-center gap-3 transition-all hover:scale-[1.02] active:scale-[0.98] text-lg"
            >
              <ShoppingBag size={24} />
              Add to Cart • ₹{mode === 'BUY' ? book.priceBuy : book.priceRent * rentWeeks}
            </button>
          </div>
        </div>
      </div>

      {/* Reviews Section */}
      <div className="w-full bg-white dark:bg-bgDark rounded-[2.5rem] p-8 md:p-12 border border-gray-100 dark:border-white/5">
         <h2 className="text-3xl font-serif font-bold text-gray-900 dark:text-cream mb-8">Ratings & Reviews</h2>

         {/* Write/Edit Review */}
         <div className="mb-12 bg-gray-50 dark:bg-bgDarker p-6 rounded-3xl border border-gray-100 dark:border-white/5 transition-all">
            <h3 className="text-xl font-bold mb-4 text-gray-800 dark:text-cream flex items-center gap-2">
              {existingReview ? (
                <><PenLine size={24} className="text-primaryGreen" /> Edit Your Review</>
              ) : (
                "Write a Review"
              )}
            </h3>
            {user ? (
              <form onSubmit={handleSubmitReview}>
                <div className="flex flex-col gap-4">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-gray-600 dark:text-gray-400">Rating:</span>
                    <div className="flex gap-1">
                      {[1,2,3,4,5].map(star => (
                        <button
                          type="button"
                          key={star}
                          onClick={() => setRating(star)}
                          onMouseEnter={() => setHoverRating(star)}
                          onMouseLeave={() => setHoverRating(0)}
                          className="transition-transform hover:scale-110 focus:outline-none"
                        >
                          <Star 
                            size={24} 
                            className={`${(hoverRating || rating) >= star ? 'fill-yellow-400 text-yellow-400' : 'text-gray-300 dark:text-gray-600'}`} 
                          />
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="relative">
                    <textarea 
                      value={reviewComment}
                      onChange={(e) => setReviewComment(e.target.value)}
                      required
                      placeholder={existingReview ? "Update your thoughts..." : "Share your thoughts about this book..."}
                      className="w-full bg-white dark:bg-bgDark rounded-xl p-4 min-h-[100px] border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen dark:text-cream resize-y"
                    />
                  </div>

                  <button 
                    type="submit"
                    className="self-end px-6 py-3 bg-primaryGreen text-white rounded-xl font-bold hover:bg-opacity-90 transition-all flex items-center gap-2 shadow-lg shadow-primaryGreen/20"
                  >
                    {existingReview ? (
                      <><PenLine size={18} /> Update Review</>
                    ) : (
                      <><Send size={18} /> Submit Review</>
                    )}
                  </button>
                </div>
              </form>
            ) : (
              <div className="text-center py-6">
                <p className="text-gray-500 mb-2">Please log in to write a review.</p>
              </div>
            )}
         </div>

         {/* Reviews List */}
         <div className="space-y-6">
            {book.reviews.length === 0 ? (
              <p className="text-center text-gray-500 italic py-8">No reviews yet. Be the first to review!</p>
            ) : (
              book.reviews.map((review) => (
                <div key={review.id} className={`border-b border-gray-100 dark:border-white/5 last:border-0 pb-6 last:pb-0 ${review.userId === user?.id ? 'bg-primaryGreen/5 p-4 rounded-xl border-none' : ''}`}>
                  <div className="flex items-start justify-between mb-3">
                     <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-gray-200 dark:bg-white/10 flex items-center justify-center text-gray-500 dark:text-gray-400">
                           <UserIcon size={20} />
                        </div>
                        <div>
                          <h4 className="font-bold text-gray-900 dark:text-cream text-sm flex items-center gap-2">
                            {review.userName}
                            {review.userId === user?.id && <span className="text-[10px] bg-primaryGreen text-white px-2 py-0.5 rounded-full">You</span>}
                          </h4>
                          <span className="text-xs text-gray-400">{review.timestamp}</span>
                        </div>
                     </div>
                     <div className="flex text-yellow-400">
                        {[1,2,3,4,5].map(star => (
                           <Star key={star} size={14} className={star <= review.rating ? 'fill-current' : 'text-gray-300 dark:text-gray-700'} />
                        ))}
                     </div>
                  </div>
                  <p className="text-gray-600 dark:text-gray-300 text-sm leading-relaxed pl-13 ml-12">
                    {review.comment}
                  </p>
                </div>
              ))
            )}
         </div>
      </div>
    </div>
  );
};

export default BookDetails;

