                 onClick={() => setIsAvatarModalOpen(false)}
                 className="text-gray-500 hover:text-gray-800 dark:hover:text-cream font-medium"
               >
                 Cancel
               </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

