import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import BookStore from './components/BookStore';
import AIHelper from './components/AIHelper';
import Community from './components/Community';
import AuthModal from './components/Auth';
import AddBookModal from './components/AddBook';
import BookDetails from './components/BookDetails';
import Cart from './components/Cart';
import Checkout from './components/Checkout';
import OrderSuccess from './components/OrderSuccess';
import Contact from './components/Contact';
import Profile from './components/Profile';
import { View, User, Book, CartItem, Review } from './types';
import { supabase } from './lib/supabase';

// Initial Data initialized to empty array to ensure only uploaded books are shown
const INITIAL_BOOKS: Book[] = [];

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.STORE);
  const [user, setUser] = useState<User | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showAddBookModal, setShowAddBookModal] = useState(false);
  const [books, setBooks] = useState<Book[]>(INITIAL_BOOKS);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // New States for Shopping Flow
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);

  // --- Supabase Integration ---

  // 1. Check for active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      if (data && data.session) {
        fetchUserProfile(data.session.user);
      }
    }).catch(err => {
      console.warn("Session check failed (likely due to missing credentials):", err);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        fetchUserProfile(session.user);
      } else {
        setUser(null);
        setCart([]); // Clear cart on logout
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // 2. Fetch Books from Supabase
  useEffect(() => {
    const fetchBooks = async () => {
      try {
        const { data, error } = await supabase.from('books').select('*').order('id', { ascending: false });
        if (error) {
          console.log("Error fetching books from Supabase:", error.message);
          return;
        }

        // Map data if available, otherwise set empty array
        const mappedBooks: Book[] = data ? data.map((b: any) => ({
          id: b.id,
          title: b.title,
          author: b.author,
          description: b.description,
          category: b.category,
          priceBuy: b.price_buy || b.priceBuy,
          markedPrice: b.marked_price || b.price_buy || b.priceBuy, // Map Marked Price
          priceRent: b.price_rent || b.priceRent,
          quantity: b.quantity !== undefined ? b.quantity : 1, // Map Quantity
          imageUrl: b.image_url || b.imageUrl,
          images: b.images || [],
          reviews: b.reviews || [],
          averageRating: b.average_rating || b.averageRating || 0,
          ownerId: b.owner_id
        })) : [];

        setBooks(mappedBooks);

      } catch (err) {
        console.error("Error connecting to DB:", err);
      }
    };
    fetchBooks();
  }, []);

  // 3. Fetch Cart logic
  const fetchUserCart = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('cart_items')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: true });

      if (error) {
        console.error("Error fetching cart:", error);
        return;
      }

      if (data) {
        const mappedCart: CartItem[] = data.map((item: any) => ({
          id: item.id.toString(),
          bookId: item.book_id,
          title: item.title,
          author: item.author,
          imageUrl: item.image_url,
          type: item.type,
          rentWeeks: item.rent_weeks,
          quantity: item.quantity,
          unitPrice: item.unit_price,
          price: item.price
        }));
        setCart(mappedCart);
      }
    } catch (err) {
      console.error("Failed to load cart");
    }
  };

  const fetchUserProfile = async (authUser: any) => {
    // Try to get profile from 'profiles' table
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .single();

      let userData: User;

      if (data && !error) {
        userData = {
          id: data.id,
          name: data.name || authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: data.avatar || authUser.user_metadata?.avatar_url,
          rentedBooks: data.rented_books || [],
          boughtBooks: data.bought_books || [],
          favoriteBooks: data.favorite_books || [],
          listedBooks: data.listed_books || [],
        };
      } else {
        // Fallback if profile table doesn't exist yet
        userData = {
          id: authUser.id,
          name: authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: authUser.user_metadata?.avatar_url,
          rentedBooks: [],
          boughtBooks: [],
          favoriteBooks: [],
          listedBooks: [],
        };
      }
      setUser(userData);
      // Once user is loaded, fetch their persistent cart
      fetchUserCart(authUser.id);

    } catch (error) {
       // Fallback on error
       const fallbackUser = {
        id: authUser.id,
        name: authUser.user_metadata?.full_name || 'User',
        email: authUser.email,
        avatar: authUser.user_metadata?.avatar_url,
        rentedBooks: [],
        boughtBooks: [],
        favoriteBooks: [],
        listedBooks: [],
      };
      setUser(fallbackUser);
      fetchUserCart(authUser.id);
    }
  };

  // --- End Supabase Integration ---

  // Toggle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setCart([]);
    setCurrentView(View.STORE);
  };

  const handleUpdateUser = async (updatedUser: User) => {
    setUser(updatedUser);

    // Persist to Supabase
    try {
      const { error } = await supabase.from('profiles').upsert({
        id: updatedUser.id,
        name: updatedUser.name,
        email: updatedUser.email,
        avatar: updatedUser.avatar,
        rented_books: updatedUser.rentedBooks,
        bought_books: updatedUser.boughtBooks,
        favorite_books: updatedUser.favoriteBooks,
        listed_books: updatedUser.listedBooks
      });

      if (error) {
        console.error("Failed to update profile:", error.message);
      }
    } catch (err) {
      console.error("Error updating user profile:", err);
    }
  };

  const handleAddBook = async (newBook: Book) => {
    // Check auth
    if (!user) {
        setShowAuthModal(true);
        return;
    }

    const bookWithOwner = { ...newBook, ownerId: user.id };

    // Optimistic Update
    setBooks([bookWithOwner, ...books]);
    const updatedUser = { ...user, listedBooks: [newBook.id, ...user.listedBooks] };
    setUser(updatedUser);
    handleUpdateUser(updatedUser);

    // Attempt to save to Supabase
    try {
      const dbBook = {
        id: newBook.id, 
        title: newBook.title,
        author: newBook.author,
        description: newBook.description,
        category: newBook.category,
        price_buy: newBook.priceBuy,
        marked_price: newBook.markedPrice, // Save MRP
        price_rent: newBook.priceRent,
        quantity: newBook.quantity, // Save Stock
        image_url: newBook.imageUrl,
        images: newBook.images,
        average_rating: newBook.averageRating,
        reviews: newBook.reviews,
        owner_id: user.id
      };

      const { error } = await supabase.from('books').insert([dbBook]);
      if (error) console.error("Error saving book to DB:", error.message);
    } catch (e) {
      console.error("Failed to save book to Supabase");
    }

    setShowAddBookModal(false);
    setCurrentView(View.STORE);
  };

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Cart Functions
  const handleAddToCart = async (item: CartItem) => {
    // Basic check locally before adding
    const book = books.find(b => b.id === item.bookId);
    if (book && item.type === 'BUY' && book.quantity < item.quantity) {
      alert("Not enough stock available.");
      return;
    }

    if (user) {
      // Sync with Supabase
      try {
        const { data, error } = await supabase.from('cart_items').insert([{
          user_id: user.id,
          book_id: item.bookId,
          title: item.title,
          author: item.author,
          image_url: item.imageUrl,
          type: item.type,
          rent_weeks: item.rentWeeks,
          quantity: item.quantity,
          unit_price: item.unitPrice,
          price: item.price
        }]).select().single();

        if (error) throw error;

        // Use the ID from the database
        const newItemWithDbId = { ...item, id: data.id.toString() };
        setCart([...cart, newItemWithDbId]);
        alert(`${item.title} added to cart!`);
      } catch (err) {
        console.error("Error adding to cart DB:", err);
        // Fallback to local state if DB fails? Or just alert error.
        alert("Failed to save item to cart.");
      }
    } else {
      // Guest mode (Local only)
      setCart([...cart, item]);
      alert(`${item.title} added to cart!`);
    }
  };

  const handleRemoveFromCart = async (itemId: string) => {
    // Optimistic update
    setCart(cart.filter(item => item.id !== itemId));

    if (user) {
      await supabase.from('cart_items').delete().eq('id', itemId);
    }
  };

  const handleUpdateQuantity = async (itemId: string, newQuantity: number) => {
    if (newQuantity < 1) return;

    // Check stock limit for buy items
    const item = cart.find(i => i.id === itemId);
    if (item && item.type === 'BUY') {
        const book = books.find(b => b.id === item.bookId);
        if (book && newQuantity > book.quantity) {
            alert("Cannot add more than available stock.");
            return;
        }
    }

    const updatedPrice = item ? item.unitPrice * (item.rentWeeks || 1) * newQuantity : 0;

    // Optimistic update
    setCart(cart.map(item => {
      if (item.id === itemId) {
        const weeks = item.type === 'RENT' ? (item.rentWeeks || 1) : 1;
        return {
          ...item,
          quantity: newQuantity,
          price: item.unitPrice * weeks * newQuantity
        };
      }
      return item;
    }));

    if (user) {
      await supabase.from('cart_items').update({ 
        quantity: newQuantity,
        price: updatedPrice
      }).eq('id', itemId);
    }
  };

  const handleUpdateRentWeeks = async (itemId: string, newWeeks: number) => {
    if (newWeeks < 1) return;

    const item = cart.find(i => i.id === itemId);
    const updatedPrice = item ? item.unitPrice * newWeeks * item.quantity : 0;

    // Optimistic Update
    setCart(cart.map(item => {
      if (item.id === itemId && item.type === 'RENT') {
        return {
          ...item,
          rentWeeks: newWeeks,
          price: item.unitPrice * newWeeks * item.quantity
        };
      }
      return item;
    }));

    if (user) {
      await supabase.from('cart_items').update({ 
        rent_weeks: newWeeks,
        price: updatedPrice
      }).eq('id', itemId);
    }
  };

  const handlePlaceOrder = async (address: any, paymentMethod: string) => {
    if (!user) {
      alert("Please login to complete purchase.");
      setShowAuthModal(true);
      return;
    }

    // 1. SAVE ORDER TO SUPABASE 'orders' TABLE
    const totalAmount = cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05);

    try {
       const { error } = await supabase.from('orders').insert([{
         user_id: user.id,
         items: cart, // Supabase handles JSON automatically
         total_amount: totalAmount,
         payment_method: paymentMethod,
         address: address,
         status: 'Confirmed'
       }]);

       if (error) {
          console.error("Order DB Insert Error:", error);
          alert("Note: Order processed but failed to save to history. Please contact support.");
       }
    } catch (err) {
       console.error("Order save exception:", err);
    }

    // 2. Decrement Stock for bought items
    const stockUpdates: Promise<any>[] = [];
    const updatedBooks = [...books];

    for (const item of cart) {
        if (item.type === 'BUY') {
            const bookIndex = updatedBooks.findIndex(b => b.id === item.bookId);
            if (bookIndex > -1) {
                // Update Local State
                updatedBooks[bookIndex].quantity = Math.max(0, updatedBooks[bookIndex].quantity - item.quantity);

                // Update Supabase
                const currentQty = updatedBooks[bookIndex].quantity; 
                stockUpdates.push(
                    supabase.from('books').update({ quantity: currentQty }).eq('id', item.bookId)
                );
            }
        }
    }

    setBooks(updatedBooks);

    try {
        await Promise.all(stockUpdates);
    } catch (err) {
        console.error("Error updating stock:", err);
    }

    // 3. Update User Profile with purchased/rented books
    const newBought = [...user.boughtBooks];
    const newRented = [...user.rentedBooks];

    cart.forEach(item => {
      if (item.type === 'BUY') newBought.push(item.bookId);
      else newRented.push(item.bookId);
    });

    const updatedUser = { ...user, boughtBooks: newBought, rentedBooks: newRented };
    handleUpdateUser(updatedUser);

    // 4. Clear Cart in DB and State
    try {
       await supabase.from('cart_items').delete().eq('user_id', user.id);
    } catch (e) {
       console.error("Error clearing cart DB", e);
    }

    setCart([]);
    setCurrentView(View.ORDER_SUCCESS);
  };

  const handleToggleFavorite = (bookId: string) => {
    if (!user) {
      setShowAuthModal(true);
      return;
    }

    const isFavorite = user.favoriteBooks.includes(bookId);
    let newFavorites;

    if (isFavorite) {
      newFavorites = user.favoriteBooks.filter(id => id !== bookId);
    } else {
      newFavorites = [...user.favoriteBooks, bookId];
    }

    const updatedUser = { ...user, favoriteBooks: newFavorites };
    handleUpdateUser(updatedUser);
  };

  const handleAddReview = async (bookId: string, review: Review) => {
    // Update local state first
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = [review, ...book.reviews];
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = Number((totalRating / newReviews.length).toFixed(1));

        const updatedBook = {
          ...book,
          reviews: newReviews,
          averageRating: avgRating
        };

        // Update Supabase
        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review DB save failed", error);
        });

        // Also update the currently selected book if it's open in details view
        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }

        return updatedBook;
      }
      return book;
    }));
  };

  const handleEditReview = async (bookId: string, updatedReview: Review) => {
    // Update local state first
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = book.reviews.map(r => r.userId === updatedReview.userId ? updatedReview : r);
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = newReviews.length > 0 ? Number((totalRating / newReviews.length).toFixed(1)) : 0;

        const updatedBook = {
          ...book,
          reviews: newReviews,
          averageRating: avgRating
        };

        // Update Supabase
        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review update DB save failed", error);
        });

        // Also update the currently selected book if it's open in details view
        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }

        return updatedBook;
      }
      return book;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      <Navbar
        currentView={currentView}
        setCurrentView={setCurrentView}
        user={user}
        onLoginClick={() => setShowAuthModal(true)}
        onLogoutClick={handleLogout}
        onPostBookClick={() => {
          if (!user) {
            setShowAuthModal(true);
          } else {
            setShowAddBookModal(true);
          }
        }}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
        cartItemCount={cart.length}
      />

      <main className="flex-grow container mx-auto px-4 py-8">
        {currentView === View.STORE && (
          <>
            <Hero />
            <BookStore
              books={books}
              user={user}
              onBookClick={(book) => {
                setSelectedBook(book);
                setCurrentView(View.BOOK_DETAILS);
              }}
              onToggleFavorite={handleToggleFavorite}
            />
          </>
        )}

        {currentView === View.BOOK_DETAILS && selectedBook && (
          <BookDetails 
            book={selectedBook} 
            user={user}
            onBack={() => {
              setSelectedBook(null);
              setCurrentView(View.STORE);
            }} 
            onAddToCart={handleAddToCart}
            onAddReview={handleAddReview}
            onEditReview={handleEditReview}
          />
        )}

        {currentView === View.CART && (
          <Cart 
            items={cart} 
            onRemove={handleRemoveFromCart}
            onUpdateQuantity={handleUpdateQuantity}
            onUpdateRentWeeks={handleUpdateRentWeeks}
            onCheckout={() => {
              if (cart.length > 0) setCurrentView(View.CHECKOUT);
            }}
            onContinueShopping={() => setCurrentView(View.STORE)}
          />
        )}

        {currentView === View.CHECKOUT && (
          <Checkout 
            total={cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05)}
            onBack={() => setCurrentView(View.CART)}
            onPlaceOrder={handlePlaceOrder}
          />
        )}

        {currentView === View.ORDER_SUCCESS && (
          <OrderSuccess onContinue={() => setCurrentView(View.STORE)} />
        )}

        {currentView === View.CONTACT && (
          <Contact />
        )}

        {currentView === View.AI_HELPER && (
          <AIHelper />
        )}

        {currentView === View.COMMUNITY && (
          <Community user={user} />
        )}

        {currentView === View.PROFILE && user && (
          <Profile 
            user={user} 
            books={books} 
            onLogout={handleLogout} 
            onUpdateUser={handleUpdateUser}
            onBookClick={(book) => {
              setSelectedBook(book);
              setCurrentView(View.BOOK_DETAILS);
            }}
          />
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import BookStore from './components/BookStore';
import AIHelper from './components/AIHelper';
import Community from './components/Community';
import AuthModal from './components/Auth';
import AddBookModal from './components/AddBook';
import BookDetails from './components/BookDetails';
import Cart from './components/Cart';
import Checkout from './components/Checkout';
import OrderSuccess from './components/OrderSuccess';
import Contact from './components/Contact';
import Profile from './components/Profile';
import { View, User, Book, CartItem, Review } from './types';
import { supabase } from './lib/supabase';
import { AlertTriangle } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.STORE);
  const [user, setUser] = useState<User | null>(null);
  const [showAuthModal, setShowAuthModal] = useState(false);
  const [showAddBookModal, setShowAddBookModal] = useState(false);
  const [books, setBooks] = useState<Book[]>([]);
  const [isDarkMode, setIsDarkMode] = useState(true);
  const [isLoadingBooks, setIsLoadingBooks] = useState(true);
  const [bookError, setBookError] = useState<string | null>(null);

  // New States for Shopping Flow
  const [selectedBook, setSelectedBook] = useState<Book | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);

  // Check if Supabase is configured
  // Accessing private property supabaseUrl for validation (casted to any to avoid TS error if property is protected)
  const isSupabaseConfigured = !(supabase as any).supabaseUrl?.includes('placeholder');

  // --- Supabase Integration ---

  // 1. Check for active session on mount
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      if (data && data.session) {
        fetchUserProfile(data.session.user);
      }
    }).catch(err => {
      console.warn("Session check failed (likely due to missing credentials):", err);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session) {
        fetchUserProfile(session.user);
      } else {
        setUser(null);
        setCart([]); // Clear cart on logout
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // 2. Fetch Books from Supabase
  useEffect(() => {
    const fetchBooks = async () => {
      setIsLoadingBooks(true);
      setBookError(null);
      try {
        const { data, error } = await supabase.from('books').select('*').order('id', { ascending: false });

        if (error) {
          console.error("Error fetching books:", error);
          setBookError(error.message);
          return;
        }

        if (data) {
          const mappedBooks: Book[] = data.map((b: any) => ({
            id: b.id.toString(), // Ensure ID is string
            title: b.title,
            author: b.author,
            description: b.description,
            category: b.category,
            priceBuy: Number(b.price_buy || b.priceBuy),
            markedPrice: Number(b.marked_price || b.price_buy || b.priceBuy),
            priceRent: Number(b.price_rent || b.priceRent),
            quantity: Number(b.quantity !== undefined ? b.quantity : 1),
            imageUrl: b.image_url || b.imageUrl,
            images: b.images || [],
            reviews: b.reviews || [],
            averageRating: Number(b.average_rating || b.averageRating || 0),
            ownerId: b.owner_id
          }));
          setBooks(mappedBooks);
        } else {
          setBooks([]);
        }
      } catch (err: any) {
        console.error("Error connecting to DB:", err);
        setBookError(err.message || "Failed to connect to database");
      } finally {
        setIsLoadingBooks(false);
      }
    };

    if (isSupabaseConfigured) {
      fetchBooks();
    } else {
      setIsLoadingBooks(false);
    }
  }, [isSupabaseConfigured]);

  // 3. Fetch Cart logic
  const fetchUserCart = async (userId: string) => {
    try {
      const { data, error } = await supabase
        .from('cart_items')
        .select('*')
        .eq('user_id', userId)
        .order('created_at', { ascending: true });

      if (error) {
        console.error("Error fetching cart:", error);
        return;
      }

      if (data) {
        const mappedCart: CartItem[] = data.map((item: any) => ({
          id: item.id.toString(),
          bookId: item.book_id,
          title: item.title,
          author: item.author,
          imageUrl: item.image_url,
          type: item.type,
          rentWeeks: item.rent_weeks,
          quantity: item.quantity,
          unitPrice: item.unit_price,
          price: item.price
        }));
        setCart(mappedCart);
      }
    } catch (err) {
      console.error("Failed to load cart");
    }
  };

  const fetchUserProfile = async (authUser: any) => {
    // Try to get profile from 'profiles' table
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authUser.id)
        .single();

      let userData: User;

      if (data && !error) {
        userData = {
          id: data.id,
          name: data.name || authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: data.avatar || authUser.user_metadata?.avatar_url,
          rentedBooks: data.rented_books || [],
          boughtBooks: data.bought_books || [],
          favoriteBooks: data.favorite_books || [],
          listedBooks: data.listed_books || [],
        };
      } else {
        // Fallback if profile table doesn't exist yet
        userData = {
          id: authUser.id,
          name: authUser.user_metadata?.full_name || 'User',
          email: authUser.email,
          avatar: authUser.user_metadata?.avatar_url,
          rentedBooks: [],
          boughtBooks: [],
          favoriteBooks: [],
          listedBooks: [],
        };
      }
      setUser(userData);
      // Once user is loaded, fetch their persistent cart
      fetchUserCart(authUser.id);

    } catch (error) {
       // Fallback on error
       const fallbackUser = {
        id: authUser.id,
        name: authUser.user_metadata?.full_name || 'User',
        email: authUser.email,
        avatar: authUser.user_metadata?.avatar_url,
        rentedBooks: [],
        boughtBooks: [],
        favoriteBooks: [],
        listedBooks: [],
      };
      setUser(fallbackUser);
      fetchUserCart(authUser.id);
    }
  };

  // --- End Supabase Integration ---

  // Toggle Dark Mode
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    setUser(null);
    setCart([]);
    setCurrentView(View.STORE);
  };

  const handleUpdateUser = async (updatedUser: User) => {
    setUser(updatedUser);

    // Persist to Supabase
    try {
      const { error } = await supabase.from('profiles').upsert({
        id: updatedUser.id,
        name: updatedUser.name,
        email: updatedUser.email,
        avatar: updatedUser.avatar,
        rented_books: updatedUser.rentedBooks,
        bought_books: updatedUser.boughtBooks,
        favorite_books: updatedUser.favoriteBooks,
        listed_books: updatedUser.listedBooks
      });

      if (error) {
        console.error("Failed to update profile:", error.message);
      }
    } catch (err) {
      console.error("Error updating user profile:", err);
    }
  };

  const handleAddBook = async (newBook: Book) => {
    // Check auth
    if (!user) {
        setShowAuthModal(true);
        return;
    }

    const bookWithOwner = { ...newBook, ownerId: user.id };

    // Optimistic Update
    setBooks([bookWithOwner, ...books]);
    const updatedUser = { ...user, listedBooks: [newBook.id, ...user.listedBooks] };
    setUser(updatedUser);
    handleUpdateUser(updatedUser);

    // Attempt to save to Supabase
    try {
      const dbBook = {
        title: newBook.title,
        author: newBook.author,
        description: newBook.description,
        category: newBook.category,
        price_buy: newBook.priceBuy,
        marked_price: newBook.markedPrice, // Save MRP
        price_rent: newBook.priceRent,
        quantity: newBook.quantity, // Save Stock
        image_url: newBook.imageUrl,
        images: newBook.images,
        average_rating: newBook.averageRating,
        reviews: newBook.reviews,
        owner_id: user.id
      };

      const { error } = await supabase.from('books').insert([dbBook]);
      if (error) {
        console.error("Error saving book to DB:", error.message);
        alert(`Failed to save to database: ${error.message}`);
      }
    } catch (e: any) {
      console.error("Failed to save book to Supabase:", e);
      alert("Failed to save book. Please check your connection.");
    }

    setShowAddBookModal(false);
    setCurrentView(View.STORE);
  };

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Cart Functions (unchanged logic)
  const handleAddToCart = async (item: CartItem) => {
    const book = books.find(b => b.id === item.bookId);
    if (book && item.type === 'BUY' && book.quantity < item.quantity) {
      alert("Not enough stock available.");
      return;
    }

    if (user) {
      try {
        const { data, error } = await supabase.from('cart_items').insert([{
          user_id: user.id,
          book_id: item.bookId,
          title: item.title,
          author: item.author,
          image_url: item.imageUrl,
          type: item.type,
          rent_weeks: item.rentWeeks,
          quantity: item.quantity,
          unit_price: item.unitPrice,
          price: item.price
        }]).select().single();

        if (error) throw error;
        const newItemWithDbId = { ...item, id: data.id.toString() };
        setCart([...cart, newItemWithDbId]);
        alert(`${item.title} added to cart!`);
      } catch (err) {
        console.error("Error adding to cart DB:", err);
        alert("Failed to save item to cart.");
      }
    } else {
      setCart([...cart, item]);
      alert(`${item.title} added to cart!`);
    }
  };

  const handleRemoveFromCart = async (itemId: string) => {
    setCart(cart.filter(item => item.id !== itemId));
    if (user) {
      await supabase.from('cart_items').delete().eq('id', itemId);
    }
  };

  const handleUpdateQuantity = async (itemId: string, newQuantity: number) => {
    if (newQuantity < 1) return;
    const item = cart.find(i => i.id === itemId);
    if (item && item.type === 'BUY') {
        const book = books.find(b => b.id === item.bookId);
        if (book && newQuantity > book.quantity) {
            alert("Cannot add more than available stock.");
            return;
        }
    }
    const updatedPrice = item ? item.unitPrice * (item.rentWeeks || 1) * newQuantity : 0;
    setCart(cart.map(item => {
      if (item.id === itemId) {
        const weeks = item.type === 'RENT' ? (item.rentWeeks || 1) : 1;
        return {
          ...item,
          quantity: newQuantity,
          price: item.unitPrice * weeks * newQuantity
        };
      }
      return item;
    }));

    if (user) {
      await supabase.from('cart_items').update({ 
        quantity: newQuantity,
        price: updatedPrice
      }).eq('id', itemId);
    }
  };

  const handleUpdateRentWeeks = async (itemId: string, newWeeks: number) => {
    if (newWeeks < 1) return;
    const item = cart.find(i => i.id === itemId);
    const updatedPrice = item ? item.unitPrice * newWeeks * item.quantity : 0;
    setCart(cart.map(item => {
      if (item.id === itemId && item.type === 'RENT') {
        return {
          ...item,
          rentWeeks: newWeeks,
          price: item.unitPrice * newWeeks * item.quantity
        };
      }
      return item;
    }));
    if (user) {
      await supabase.from('cart_items').update({ 
        rent_weeks: newWeeks,
        price: updatedPrice
      }).eq('id', itemId);
    }
  };

  const handlePlaceOrder = async (address: any, paymentMethod: string) => {
    if (!user) {
      alert("Please login to complete purchase.");
      setShowAuthModal(true);
      return;
    }
    const totalAmount = cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05);

    try {
       const { error } = await supabase.from('orders').insert([{
         user_id: user.id,
         items: cart,
         total_amount: totalAmount,
         payment_method: paymentMethod,
         address: address,
         status: 'Confirmed'
       }]);

       if (error) {
          console.error("Order DB Insert Error:", error);
          alert("Note: Order processed but failed to save to history. Please contact support.");
       }
    } catch (err) {
       console.error("Order save exception:", err);
    }

    const stockUpdates: Promise<any>[] = [];
    const updatedBooks = [...books];

    for (const item of cart) {
        if (item.type === 'BUY') {
            const bookIndex = updatedBooks.findIndex(b => b.id === item.bookId);
            if (bookIndex > -1) {
                updatedBooks[bookIndex].quantity = Math.max(0, updatedBooks[bookIndex].quantity - item.quantity);
                const currentQty = updatedBooks[bookIndex].quantity; 
                stockUpdates.push(
                    supabase.from('books').update({ quantity: currentQty }).eq('id', item.bookId)
                );
            }
        }
    }

    setBooks(updatedBooks);
    try {
        await Promise.all(stockUpdates);
    } catch (err) {
        console.error("Error updating stock:", err);
    }

    const newBought = [...user.boughtBooks];
    const newRented = [...user.rentedBooks];
    cart.forEach(item => {
      if (item.type === 'BUY') newBought.push(item.bookId);
      else newRented.push(item.bookId);
    });

    const updatedUser = { ...user, boughtBooks: newBought, rentedBooks: newRented };
    handleUpdateUser(updatedUser);

    try {
       await supabase.from('cart_items').delete().eq('user_id', user.id);
    } catch (e) {
       console.error("Error clearing cart DB", e);
    }

    setCart([]);
    setCurrentView(View.ORDER_SUCCESS);
  };

  const handleToggleFavorite = (bookId: string) => {
    if (!user) {
      setShowAuthModal(true);
      return;
    }
    const isFavorite = user.favoriteBooks.includes(bookId);
    let newFavorites;
    if (isFavorite) {
      newFavorites = user.favoriteBooks.filter(id => id !== bookId);
    } else {
      newFavorites = [...user.favoriteBooks, bookId];
    }
    const updatedUser = { ...user, favoriteBooks: newFavorites };
    handleUpdateUser(updatedUser);
  };

  const handleAddReview = async (bookId: string, review: Review) => {
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = [review, ...book.reviews];
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = Number((totalRating / newReviews.length).toFixed(1));

        const updatedBook = { ...book, reviews: newReviews, averageRating: avgRating };

        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review DB save failed", error);
        });

        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }
        return updatedBook;
      }
      return book;
    }));
  };

  const handleEditReview = async (bookId: string, updatedReview: Review) => {
    setBooks(prevBooks => prevBooks.map(book => {
      if (book.id === bookId) {
        const newReviews = book.reviews.map(r => r.userId === updatedReview.userId ? updatedReview : r);
        const totalRating = newReviews.reduce((sum, r) => sum + r.rating, 0);
        const avgRating = newReviews.length > 0 ? Number((totalRating / newReviews.length).toFixed(1)) : 0;

        const updatedBook = { ...book, reviews: newReviews, averageRating: avgRating };

        supabase.from('books').update({
          reviews: newReviews,
          average_rating: avgRating
        }).eq('id', bookId).then(({ error }) => {
           if (error) console.log("Review update DB save failed", error);
        });

        if (selectedBook && selectedBook.id === bookId) {
           setSelectedBook(updatedBook);
        }
        return updatedBook;
      }
      return book;
    }));
  };

  return (
    <div className="min-h-screen flex flex-col font-sans transition-colors duration-300">
      <Navbar
        currentView={currentView}
        setCurrentView={setCurrentView}
        user={user}
        onLoginClick={() => setShowAuthModal(true)}
        onLogoutClick={handleLogout}
        onPostBookClick={() => {
          if (!user) {
            setShowAuthModal(true);
          } else {
            setShowAddBookModal(true);
          }
        }}
        isDarkMode={isDarkMode}
        toggleTheme={toggleTheme}
        cartItemCount={cart.length}
      />

      <main className="flex-grow container mx-auto px-4 py-8">

        {!isSupabaseConfigured && (
          <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-6" role="alert">
            <strong className="font-bold flex items-center gap-2"><AlertTriangle size={20}/> Configuration Error: </strong>
            <span className="block sm:inline">Supabase keys are missing. Please add VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY to your environment variables. The app is currently in read-only/offline mode.</span>
          </div>
        )}

        {currentView === View.STORE && (
          <>
            <Hero />
            <BookStore
              books={books}
              user={user}
              isLoading={isLoadingBooks}
              error={bookError}
              onBookClick={(book) => {
                setSelectedBook(book);
                setCurrentView(View.BOOK_DETAILS);
              }}
              onToggleFavorite={handleToggleFavorite}
            />
          </>
        )}

        {currentView === View.BOOK_DETAILS && selectedBook && (
          <BookDetails 
            book={selectedBook} 
            user={user}
            onBack={() => {
              setSelectedBook(null);
              setCurrentView(View.STORE);
            }} 
            onAddToCart={handleAddToCart}
            onAddReview={handleAddReview}
            onEditReview={handleEditReview}
          />
        )}

        {currentView === View.CART && (
          <Cart 
            items={cart} 
            onRemove={handleRemoveFromCart}
            onUpdateQuantity={handleUpdateQuantity}
            onUpdateRentWeeks={handleUpdateRentWeeks}
            onCheckout={() => {
              if (cart.length > 0) setCurrentView(View.CHECKOUT);
            }}
            onContinueShopping={() => setCurrentView(View.STORE)}
          />
        )}

        {currentView === View.CHECKOUT && (
          <Checkout 
            total={cart.reduce((sum, item) => sum + item.price, 0) + Math.round(cart.reduce((sum, item) => sum + item.price, 0) * 0.05)}
            onBack={() => setCurrentView(View.CART)}
            onPlaceOrder={handlePlaceOrder}
          />
        )}

        {currentView === View.ORDER_SUCCESS && (
          <OrderSuccess onContinue={() => setCurrentView(View.STORE)} />
        )}

        {currentView === View.CONTACT && (
          <Contact />
        )}

        {currentView === View.AI_HELPER && (
          <AIHelper />
        )}

        {currentView === View.COMMUNITY && (
          <Community user={user} />
        )}

        {currentView === View.PROFILE && user && (
          <Profile 
            user={user} 
            books={books} 
            onLogout={handleLogout} 
            onUpdateUser={handleUpdateUser}
            onBookClick={(book) => {
              setSelectedBook(book);
              setCurrentView(View.BOOK_DETAILS);
            }}
          />
        )}
      </main>

      {/* Modals */}
      {showAuthModal && (
        <AuthModal onClose={() => setShowAuthModal(false)} />
      )}
      {showAddBookModal && (
        <AddBookModal onClose={() => setShowAddBookModal(false)} onAddBook={handleAddBook} />
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, AuthMode } from '../types';
import { X, Mail, Lock, User as UserIcon, Loader2, AlertCircle } from 'lucide-react';
import { supabase } from '../lib/supabase';

interface AuthModalProps {
  onClose: () => void;
  onLogin?: (user: User) => void;
}

const AuthModal: React.FC<AuthModalProps> = ({ onClose }) => {
  const [mode, setMode] = useState<AuthMode>(AuthMode.LOGIN);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      if (mode === AuthMode.SIGNUP) {
        // --- SIGN UP ---
        const { data, error } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              full_name: name,
            },
          },
        });

        if (error) throw error;

        if (data.user) {
          // Check if session exists (auto-confirmed) or if email verification is required
          if (data.session) {
             onClose();
          } else {
             // If user created but no session, they probably need to verify email
             alert("Sign up successful! Please check your email to verify your account before logging in.");
             setMode(AuthMode.LOGIN); // Switch to login view
          }
        }
      } else {
        // --- LOG IN ---
        const { data, error } = await supabase.auth.signInWithPassword({
          email,
          password,
        });

        if (error) {
           if (error.message.includes('Email not confirmed')) {
             throw new Error("Your email address has not been verified yet. Please check your inbox.");
           } else if (error.message.includes('Invalid login credentials')) {
             throw new Error("Invalid email or password. Please try again.");
           } else {
             throw error;
           }
        }

        // App.tsx's onAuthStateChange listener will handle the state update
        onClose();
      }
    } catch (err: any) {
      console.error("Auth error:", err);
      setError(err.message || "Authentication failed. Please check your credentials.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white dark:bg-bgDark w-full max-w-md rounded-3xl p-8 relative shadow-2xl border border-gray-200 dark:border-primaryGreen/30 animate-in fade-in zoom-in duration-200">
        <button 
          onClick={onClose}
          className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 dark:hover:text-cream transition-colors"
        >
          <X size={24} />
        </button>

        <h2 className="text-3xl font-serif font-bold text-center mb-2 text-gray-900 dark:text-cream">
          {mode === AuthMode.LOGIN ? 'Welcome Back' : 'Join Bookgram'}
        </h2>
        <p className="text-center text-gray-500 mb-8">
          {mode === AuthMode.LOGIN ? 'Curate your intellect today.' : 'Start your journey of knowledge.'}
        </p>

        {error && (
          <div className="mb-6 p-4 bg-red-50 dark:bg-red-900/10 border border-red-200 dark:border-red-800 text-red-600 dark:text-red-300 rounded-xl text-sm flex items-start gap-3">
            <AlertCircle className="flex-shrink-0 mt-0.5" size={18} />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {mode === AuthMode.SIGNUP && (
            <div className="relative">
              <UserIcon className="absolute left-4 top-3.5 text-gray-400" size={20} />
              <input
                type="text"
                placeholder="Full Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required={mode === AuthMode.SIGNUP}
                className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-12 pr-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors"
              />
            </div>
          )}

          <div className="relative">
            <Mail className="absolute left-4 top-3.5 text-gray-400" size={20} />
            <input
              type="email"
              placeholder="Email Address"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-12 pr-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors"
            />
          </div>

          <div className="relative">
            <Lock className="absolute left-4 top-3.5 text-gray-400" size={20} />
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="w-full bg-gray-50 dark:bg-bgDarker text-gray-900 dark:text-cream pl-12 pr-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 focus:outline-none focus:border-primaryGreen transition-colors"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-primaryGreen hover:bg-opacity-90 text-white font-bold py-3.5 rounded-xl shadow-lg shadow-primaryGreen/20 transition-all transform active:scale-95 flex items-center justify-center gap-2"
          >
            {loading && <Loader2 size={18} className="animate-spin" />}
            {mode === AuthMode.LOGIN ? 'Log In' : 'Sign Up'}
          </button>
        </form>

        <div className="mt-6 text-center">
          <p className="text-gray-500 text-sm">
            {mode === AuthMode.LOGIN ? "Don't have an account? " : "Already have an account? "}
            <button 
              onClick={() => {
                setMode(mode === AuthMode.LOGIN ? AuthMode.SIGNUP : AuthMode.LOGIN);
                setError(null);
              }}
              className="text-primaryGreen font-bold hover:underline"
            >
              {mode === AuthMode.LOGIN ? 'Sign Up' : 'Log In'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default AuthModal;

import React, { useState } from 'react';
import { Book, User } from '../types';
import { Heart, Star, Loader2, Database } from 'lucide-react';

interface BookStoreProps {
  books: Book[];
  user: User | null;
  onBookClick: (book: Book) => void;
  onToggleFavorite: (bookId: string) => void;
  isLoading?: boolean;
  error?: string | null;
}

const CATEGORIES = ['All', 'Competitive Exams', 'Engineering', 'Medical', 'Arts & Humanities', 'Fiction', 'Non-Fiction'];

const BookStore: React.FC<BookStoreProps> = ({ books, user, onBookClick, onToggleFavorite, isLoading, error }) => {
  const [selectedCategory, setSelectedCategory] = useState('All');

  const filteredBooks = selectedCategory === 'All' 
    ? books 
    : books.filter(b => b.category === selectedCategory);

  return (
    <div className="w-full space-y-8 min-h-[500px]">
      {/* Categories */}
      <div className="flex flex-wrap gap-2 md:gap-3 justify-center">
        {CATEGORIES.map((cat) => (
          <button
            key={cat}
            onClick={() => setSelectedCategory(cat)}
            className={`px-3 py-1.5 md:px-5 md:py-2.5 rounded-2xl text-xs md:text-sm font-medium transition-all duration-200 border ${
              selectedCategory === cat
                ? 'bg-bgDarker text-cream border-bgDarker dark:bg-cream dark:text-bgDarker dark:border-cream'
                : 'bg-transparent text-gray-600 dark:text-gray-400 border-gray-300 dark:border-white/10 hover:border-primaryGreen hover:text-primaryGreen'
            }`}
          >
            {cat}
          </button>
        ))}
      </div>

      {/* Loading State */}
      {isLoading && (
         <div className="flex flex-col items-center justify-center py-20 text-gray-500 dark:text-gray-400">
            <Loader2 size={48} className="animate-spin text-primaryGreen mb-4" />
            <p>Fetching books from the archives...</p>
         </div>
      )}

      {/* Error State */}
      {!isLoading && error && (
         <div className="flex flex-col items-center justify-center py-20 text-red-500 bg-red-50 dark:bg-red-900/10 rounded-3xl border border-red-200 dark:border-red-900/30">
            <Database size={48} className="mb-4" />
            <p className="font-bold text-lg mb-2">Connection Error</p>
            <p className="text-sm max-w-md text-center">{error}</p>
         </div>
      )}

      {/* Empty State */}
      {!isLoading && !error && filteredBooks.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 text-gray-500 dark:text-gray-400">
             <div className="w-20 h-20 bg-gray-100 dark:bg-white/5 rounded-full flex items-center justify-center mb-4">
                <Database size={32} />
             </div>
             <h3 className="text-xl font-bold mb-2">No books found</h3>
             <p className="max-w-md text-center text-sm">
                If you have uploaded books to Supabase, they might be hidden due to Row Level Security (RLS) policies. Ensure you have a 'SELECT' policy enabled for the 'books' table.
             </p>
          </div>
      )}

      {/* Grid */}
      {!isLoading && !error && filteredBooks.length > 0 && (
        <div className="grid grid-cols-4 gap-2 md:gap-4 lg:gap-6">
          {filteredBooks.map((book) => {
            const isFavorite = user?.favoriteBooks.includes(book.id);
            const isOutOfStock = book.quantity === 0;
            const discount = book.markedPrice > book.priceBuy 
              ? Math.round(((book.markedPrice - book.priceBuy) / book.markedPrice) * 100) 
              : 0;

            return (
              <div 
                key={book.id}
                onClick={() => onBookClick(book)}
                className={`group cursor-pointer bg-white dark:bg-bgDarker rounded-xl md:rounded-3xl overflow-hidden border border-gray-200 dark:border-white/5 hover:border-primaryGreen/50 transition-all duration-300 hover:shadow-2xl hover:shadow-primaryGreen/10 flex flex-col h-full relative ${isOutOfStock ? 'opacity-80' : ''}`}
              >
                {/* Image */}
                <div className="relative aspect-[3/4] overflow-hidden bg-gray-100 dark:bg-gray-800">
                  <img 
                    src={book.imageUrl} 
                    alt={book.title}
                    className={`w-full h-full object-cover transition-transform duration-500 group-hover:scale-110 ${isOutOfStock ? 'grayscale' : ''}`}
                    loading="lazy"
                  />

                  {isOutOfStock && (
                    <div className="absolute inset-0 bg-black/50 flex items-center justify-center z-10">
                      <span className="bg-red-600 text-white px-3 py-1 text-sm font-bold uppercase tracking-wider transform -rotate-12 border-2 border-white">Out of Stock</span>
                    </div>
                  )}

                  {!isOutOfStock && discount > 0 && (
                    <div className="absolute top-0 left-0 bg-primaryGreen text-white text-[10px] md:text-xs font-bold px-2 py-1 rounded-br-lg z-10">
                      {discount}% OFF
                    </div>
                  )}

                  <button 
                    onClick={(e) => { 
                      e.stopPropagation(); 
                      onToggleFavorite(book.id); 
                    }}
                    className={`absolute top-2 right-2 md:top-4 md:right-4 w-6 h-6 md:w-8 md:h-8 rounded-full backdrop-blur-md flex items-center justify-center transition-colors z-20 ${
                      isFavorite 
                        ? 'bg-red-500 text-white hover:bg-red-600' 
                        : 'bg-white/20 text-white hover:bg-red-500'
                    }`}
                  >
                    <Heart size={14} className={`md:w-4 md:h-4 ${isFavorite ? 'fill-current' : ''}`} />
                  </button>
                  <div className="absolute bottom-2 left-2 md:bottom-4 md:left-4 bg-bgDarker/80 backdrop-blur-sm text-cream text-[10px] md:text-xs px-2 py-0.5 md:px-3 md:py-1 rounded-full uppercase tracking-wider font-bold truncate max-w-[80%]">
                    {book.category}
                  </div>
                </div>

                {/* Content */}
                <div className="p-2 md:p-5 flex flex-col flex-grow">
                  <div className="mb-2">
                    <h3 className="font-serif text-xs sm:text-sm md:text-xl font-bold text-gray-900 dark:text-cream leading-tight mb-1 line-clamp-1 group-hover:text-primaryGreen transition-colors">
                      {book.title}
                    </h3>
                    <p className="text-[10px] md:text-sm text-gray-500 dark:text-gray-400 font-medium truncate">{book.author}</p>
                  </div>

                  <div className="hidden sm:flex items-center gap-1 mb-2 md:mb-4">
                    <div className="flex">
                      {[1,2,3,4,5].map(star => (
                        <Star 
                          key={star} 
                          size={12} 
                          className={`${
                            star <= Math.round(book.averageRating || 0) 
                              ? 'fill-yellow-400 text-yellow-400' 
                              : 'text-gray-300 dark:text-gray-600'
                          }`} 
                        />
                      ))}
                    </div>
                    <span className="text-xs text-gray-400 ml-1">({book.averageRating || 0})</span>
                  </div>

                  <div className="space-y-3 mt-auto">
                    <div className="flex flex-col xl:flex-row items-start xl:items-center justify-between p-2 md:p-3 bg-gray-50 dark:bg-white/5 rounded-lg md:rounded-xl gap-1">
                      <div className="flex flex-col">
                          <span className="text-[10px] md:text-xs text-gray-500 dark:text-gray-400">Rent</span>
                          <span className="font-bold text-xs md:text-base text-primaryGreen">₹{book.priceRent}<span className="hidden md:inline text-[10px] md:text-xs text-gray-400 font-normal">/wk</span></span>
                      </div>
                      <div className="hidden xl:block w-px h-8 bg-gray-200 dark:bg-white/10"></div>
                      <div className="flex flex-col xl:items-end">
                          <span className="text-[10px] md:text-xs text-gray-500 dark:text-gray-400">Buy</span>
                          <div className="flex flex-col xl:items-end leading-tight">
                            {discount > 0 && <span className="text-[8px] md:text-[10px] text-gray-400 line-through">₹{book.markedPrice}</span>}
                            <span className="font-bold text-xs md:text-base text-gray-900 dark:text-cream">₹{book.priceBuy}</span>
                          </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

